async function persist(){
 clearTimeout(autosaveTimer);autosaveTimer=null;
 if(saveConflictId===project.id){$('saveStatus').textContent='! Conflict — review before saving';return false;}
 // Capture the exact state before asynchronous writes: a later project switch cannot
 // redirect this save to another project. Serialize writes to prevent out-of-order saves.
 const snapshot=structuredClone(project),id=snapshot.id,sequence=editSequence;
 const write=saveQueue.catch(()=>{}).then(async()=>{
  const expected=confirmedRevisions.has(id)?confirmedRevisions.get(id):snapshot._storageRevision||null;
  const revision=newId('revision');snapshot._storageRevision=revision;
  // A checkpoint contains the previous verified document, not the unsaved one.
  // Automatic recovery is best-effort and never prevents an ordinary project save.
  try{
   let previousCheckpoint=recoveryTime.get(id);
   if(previousCheckpoint===undefined){const existing=await listCheckpoints(id);previousCheckpoint=existing[0]?Date.parse(existing[0].time):0;recoveryTime.set(id,previousCheckpoint);}
   if(Date.now()-previousCheckpoint>=300000){
    const previous=await getProject(id);
    if(previous&&previous.updatedAt!==snapshot.updatedAt){await createCheckpoint(previous,'Automatic recovery');recoveryTime.set(id,Date.now());}
   }
  }catch(error){console.warn('Optional recovery checkpoint skipped',error);recoveryTime.set(id,Date.now());}
  await saveProjectIfCurrent(snapshot,expected);
  confirmedRevisions.set(id,revision);
  // V3.59: verify against the small summary record when available (avoids reading a large project back).
  const savedRevision=storageModule.getProjectRevision?await storageModule.getProjectRevision(id):(await getProject(id))?._storageRevision;
  if(savedRevision!==revision)throw new Error('Save verification failed');
  return await listProjects();
 });
 saveQueue=write;
 try{
  const latest=await write;recent=latest;
  if(project.id===id){project._storageRevision=snapshot._storageRevision;if(editSequence===sequence)hasUnsavedWork=false;saveFailed=false;lastSaved=new Date().toLocaleTimeString();
   if(editSequence===sequence){$('saveStatus').textContent='● Saved locally';$('statusLeft').textContent='● Ready · Changes saved locally';}
   localStorage.setItem('openviz-active-project',id);
  }
  if(ui.page==='home')renderHome();
  return true;
 }catch(e){console.error('Local save failed',e);
  if(project.id===id){
   saveFailed=true;
   if(e.code==='STORAGE_CONFLICT'){
    const first=saveConflictId!==id;saveConflictId=id;
    $('saveStatus').textContent='! Conflict — review before saving';
    $('statusLeft').textContent='! Other tab changed this project · Save as a separate copy';
    if(first)openSaveConflict();
   }else{$('saveStatus').textContent='! Save unavailable';$('statusLeft').textContent='! Local storage unavailable — export your project';}
  }
  return false;
 }
}
