function renameProject(){const name=prompt('Project name',project.name);if(!name?.trim())return;trackChange();project.name=name.trim().slice(0,120);markDirty();render();}
function deleteChart(){const c=chart();if(!c)return;if(!confirm(`Delete "${c.title}"? It will also be removed from dashboards and slides.`))return;trackChange();project.charts=project.charts.filter(x=>x.id!==c.id);project.dashboards.forEach(d=>d.chartIds=d.chartIds.filter(id=>id!==c.id));project.slides.forEach(s=>s.objects=s.objects.filter(o=>o.chartId!==c.id));storyList().forEach(st=>st.scenes=st.scenes.filter(sc=>sc.chartId!==c.id));ui.selectedChartId=project.charts[0]?.id||null;markDirty();render();}
