 const section=(label,count,action,items)=>{const key=label.toLowerCase().replace(/ /g,'-');return `<div class="section-tree"><details class="tree-section" data-tree-section="${key}" ${ui.treeSections[key]!==false?'open':''}><summary class="tree-heading"><span class="tree-disclosure" aria-hidden="true">›</span><span>${label}</span><span class="count">(${count})</span></summary><div class="tree-section-items">${items||'<p class="hint" style="margin:4px 10px 8px 21px">None yet</p>'}</div></details><button class="tree-section-add" data-action="${action}" aria-label="Add ${label.toLowerCase()}" title="Add ${label.toLowerCase()}">+</button></div>`;};
