function highlightSelectedChartPart(){const root=$('liveChartSvg');root?.querySelectorAll('[data-viz-part]').forEach(el=>{const sel=ui.chartSelection;el.classList.toggle('selected-viz-part',!!sel&&el.dataset.vizPart===sel.part&&(sel.part!=='point'||decodeURIComponent(el.dataset.vizKey||'')===sel.key)&&(sel.part!=='annotation'||ui.annotationSelection.includes(el.dataset.annotationId)));});}
