// V1.8 dashboard supports a responsive grid and a precision free-canvas layout.
// The free layout stores chart IDs and geometry only; visualisations remain linked to their data.
function ensureDashboardItems(dash){
 dash.items=Array.isArray(dash.items)?dash.items.filter(it=>dash.chartIds.includes(it.chartId)):[];
 for(const [i,id] of dash.chartIds.entries())if(!dash.items.some(it=>it.chartId===id))dash.items.push({chartId:id,x:i%2?51:3,y:24+Math.floor(i/2)*326,w:46,h:295});
 if(![700,900,1200,1600].includes(dash.canvasHeight))dash.canvasHeight=900;
 return dash.items;
}
