function stopMotionPlayback(){if(motionAnimationId!==null)cancelAnimationFrame(motionAnimationId);motionAnimationId=null;}
function motionFrame(time){if(!motionStudio)return;const stage=$('motionStage');if(!stage)return;const svg=motionStudio.cleanSvg?.cloneNode(true);if(!svg)return;setMotionFrame(svg,time,motionStudio.motion);stage.replaceChildren(svg);const input=$('motionScrub');if(input)input.value=String(Math.round(time));const clock=$('motionClock');if(clock)clock.textContent=(time/1000).toFixed(2)+' s';}
