 const m=motionStudio.motion;
 openModal('Motion timeline',`<p class="muted">Animate the visualisation marks, not the underlying data. Preview or scrub the timeline, then save settings or export a GIF/video. Static SVG, PNG and PowerPoint remain unchanged.</p><div class="motion-studio"><div class="motion-preview"><div id="motionStage" class="motion-frame">${motionStudio.source}</div><div class="motion-playback"><button class="secondary-button" data-action="motion-play">▶ Play</button><button class="secondary-button" data-action="motion-stop">■ Stop</button><span id="motionClock">0.00 s</span></div><div class="motion-segments" aria-label="Animation phases"><span id="motionSegmentdelay" title="Start delay"></span><span id="motionSegmentintro" title="Intro"></span><span id="motionSegmenthold" title="Hold"></span><span id="motionSegmentoutro" title="Outro"></span></div><input id="motionScrub" type="range" min="0" max="${motionDuration(m)}" value="0" step="10" aria-label="Scrub animation timeline"><div class="motion-phase-labels"><span>Delay</span><span>Reveal</span><span>Hold</span><span>Outro</span></div></div><div class="motion-controls">${[['effect','Effect'],['easing','Easing']].map(([key,name])=>`<label class="field"><span>${name}</span><select data-motion-setting="${key}">${(key==='effect'?[...chartMotionOptions(c.type),['stagger','Fade marks one by one'],['rise','Cinematic rise (may cross axes)']]:['ease-out','linear','ease-in','ease-in-out'].map(v=>[v,v])).map(([value,label])=>`<option value="${value}" ${m[key]===value?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}${[['delay','Start delay'],['intro','Reveal duration'],['hold','Hold duration'],['outro','Outro duration'],['fps','Frames/second']].map(([key,label])=>`<label class="field"><span>${label} (${key==='fps'?'fps':'ms'})</span><input type="number" data-motion-setting="${key}" value="${m[key]}" min="0" max="${key==='fps'?20:8000}" step="${key==='fps'?1:50}"></label>`).join('')}</div></div><div class="motion-actions"><span id="motionProgress" role="status">Motion is preview-only until you save it.</span><button class="secondary-button" data-action="motion-gif">Export GIF</button><button class="secondary-button" data-action="motion-video">Export ${preferredVideoType()?.includes('mp4')?'MP4':'WebM'} video</button><button class="primary" data-action="motion-apply">Save motion settings</button></div><p class="hint">Bar growth stays within the plot; avoid Rise for charts where moving marks beyond axes would mislead. GIF uses a 256-colour palette. Video recording runs in real time; formats depend on browser support. Reduced-motion settings suppress automatic playback, but manually requested exports still work.</p>`,true);
