let menuReturnFocus=null;
function closeMenus(){if(activeMenu&&document.activeElement?.closest?.('#menuPopover,#chartContextMenu'))menuReturnFocus={el:document.querySelector(`[data-menu="${CSS.escape(activeMenu)}"]`),at:Date.now()};for(const id of ['menuPopover','chartContextMenu']){const el=$(id);if(el){el.classList.add('hidden');el.innerHTML='';}}document.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));activeMenu=null;}
