function openChartContext(id,x,y){closeMenus();const c=project.charts.find(v=>v.id===id);if(!c)return;rightClickChartId=id;const root=$('chartContextMenu');root.innerHTML=`<div class="floating-menu-title">${E(c.title)}</div><button data-action="ctx-edit">Open / edit</button><button data-action="ctx-duplicate">Duplicate</button><button data-action="ctx-rename">Rename…</button><button data-action="ctx-change">Change chart type…</button><button data-action="ctx-add-dashboard">Add to dashboard</button><button data-action="ctx-add-slide">Add to presentation</button><div class="floating-separator"></div><button data-action="ctx-version">Save design version</button><button data-action="ctx-export">Export…</button><div class="floating-separator"></div><button class="danger-text" data-action="ctx-delete">Delete chart</button>`;positionMenu(root,x,y);}
function openPublicationStyles(){const styles=[['none','No figure formatting','Use normal chart titles and labels, with no publication caption.'],['apa7','APA 7 inspired','Figure number and italic descriptive title above; optional note below.'],['chicago','Chicago inspired','Figure number and caption below, with optional source or explanatory note.'],['mla','MLA inspired','Fig. number and description below the visualisation.'],['ieee','IEEE inspired','Compact Fig. caption below, intended for technical figures.']];openModal('Figure & referencing styles',`<p class="muted" style="margin-bottom:14px">These are editable figure layout presets, <strong>not</strong> bibliography generators or automatic style compliance certificates. Confirm your assignment, journal or organisation's requirements.</p>${styles.map(([id,name,desc])=>`<button class="modal-choice" data-action="set-publication-style" data-style="${id}"><span class="choice-icon">▤</span><span><strong>${E(name)}</strong><small>${E(desc)}</small></span></button>`).join('')}`);}
function applyPublicationStyle(style){if(!['none','apa7','chicago','mla','ieee'].includes(style))return;const c=chart();if(!c)return;trackChange();if(style==='none'){c.publicationStyle='none';c.showTitle=true;c.showSubtitle=false;}else{Object.assign(c,{publicationStyle:style,figureNumber:c.figureNumber||'Figure 1',figureTitle:c.figureTitle||c.title||'Untitled figure',showFigureNumber:true,showFigureTitle:true,figureNote:c.figureNote||'',font:'Arial, sans-serif',background:'#ffffff',textColor:'#111111',gridColor:'#d0d0d0',showGrid:false,showAxes:true,showTitle:false,showSubtitle:false,transparent:false,labelSize:12,barRadius:0,padding:55,width:960,height:620});}
 ui.inspectorTab='publication';ui.chartSelection=null;markDirty();closeModal();render();showToast(`${style.toUpperCase()} figure layout applied; check publisher or institutional rules before submission`);}
function applyApa7(){const c=chart();if(!c)return;trackChange();Object.assign(c,{publicationStyle:'apa7',figureNumber:c.figureNumber||'Figure 1',figureTitle:c.figureTitle||c.title||'Untitled figure',showFigureTitle:true,figureNote:c.figureNote||'',font:'Arial, sans-serif',color:'#222222',secondary:'#777777',background:'#ffffff',textColor:'#111111',gridColor:'#D0D0D0',showGrid:false,showAxes:true,showTitle:false,showSubtitle:false,showLegend:false,transparent:false,titleSize:20,labelSize:12,barRadius:0,padding:45,width:960,height:600});ui.inspectorTab='publication';markDirty();render();showToast('APA 7 figure preset applied — review against your assignment or publication requirements');}
