async function openReleaseDiagnostics(){lastReleaseDiagnostics=null;
 openModal('V3.4 · Release diagnostics',`<p class="muted">Run these checks on the browser and origin where you actually use OpenViz. They do not send data to a server, modify the active project, or prove compatibility with every browser.</p><div id="releaseDiagnosticResults" role="status" aria-live="polite"><p>Checks have not been run.</p></div><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Close</button><button class="secondary-button" data-action="release-download-diagnostics" id="releaseDownloadReport" disabled>Download report</button><button class="primary" data-action="release-run-diagnostics">Run checks</button></div>`,true);
}
async function runReleaseDiagnostics(){
 const results=$('releaseDiagnosticResults');if(!results)return;
 results.innerHTML='<p>Checking local storage, SVG rendering, project round-trip and export support…</p>';
 const checks=[];const check=async(name,work)=>{try{const summary=await work();checks.push({name,pass:true,summary});}catch(error){checks.push({name,pass:false,summary:String(error.message||error)});}};
 await check('IndexedDB read/write/delete',async()=>{const result=await testLocalStorage();return `${result.persisted?'Persistent storage granted':'Storage persistence not guaranteed'} · ${friendlyBytes(result.usage)} used`;});
 await check('Portable project and JSON consistency',async()=>{const snapshot=structuredClone(project);const roundTrip=JSON.parse(JSON.stringify(snapshot));if(roundTrip.id!==project.id||roundTrip.charts.length!==project.charts.length||roundTrip.datasets.length!==project.datasets.length)throw Error('Project round-trip mismatch');return `${snapshot.datasets.length} datasets · ${snapshot.charts.length} charts · ${snapshot.slides.length} slides`;});
 await check('Project persistence across a database read',async()=>{
  const id=newId('release-probe'),probe={formatVersion:1,id,name:'Temporary release probe',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),datasets:[{id:'sample',name:'Probe',rows:[{Country:'New Zealand',Value:7}],rawRows:[{Country:'New Zealand',Value:7}],calculations:[]}],charts:[],dashboards:[],slides:[],stories:[],versions:[]};
  try{
   await saveProject(probe);const loaded=await getProject(id);
   if(JSON.stringify(loaded)!==JSON.stringify(probe))throw Error('Saved project does not match read-back project');
   const newRevision=newId('revision');await saveProjectIfCurrent({...loaded,_storageRevision:newRevision},null);
   let blocked=false;try{await saveProjectIfCurrent({...loaded,_storageRevision:newId('revision')},null);}catch(error){blocked=error.code==='STORAGE_CONFLICT';}
   const after=await getProject(id);
   if(!blocked||after?._storageRevision!==newRevision)throw Error('Stale save was not blocked');
   return 'Saved/read back exactly; simultaneous stale write safely blocked';
  }
  finally{try{await deleteProject(id);}catch(error){console.warn('Unable to clean up temporary release probe',error);}}
 });
 await check('SVG chart rendering',async()=>{const d=dataset(),c=chart();if(!d||!c)return 'No chart present · use the sample project to check rendering';const svg=buildChart(d.rows,c,c.type,{width:640,height:360});const parsed=new DOMParser().parseFromString(svg,'image/svg+xml');if(parsed.querySelector('parsererror')||parsed.documentElement.nodeName.toLowerCase()!=='svg')throw Error('Invalid chart SVG');return `Valid ${c.type} SVG · ${svg.length.toLocaleString()} characters`;});
 await check('Animation/recording availability',async()=>{const hasCanvas=!!document.createElement('canvas').getContext('2d');if(!hasCanvas)throw Error('Canvas 2D unavailable');return `Canvas ready; ${typeof MediaRecorder==='function'?'video recording available':'video recording unavailable'}; reduced motion ${matchMedia('(prefers-reduced-motion:reduce)').matches?'enabled':'not requested'}`;});
 await check('Synthetic 20,000-row preview budget',async()=>{
  // Fixed synthetic rows: no project values leave the browser or enter the report.
  const rows=Array.from({length:20000},(_,i)=>({X:i,Y:Math.sin(i*.013)*50+i%9}));
  const spec={...DEFAULT_CHART,type:'scatter',x:'X',y:'Y',title:'Local performance check'};
  const started=performance.now();const svg=buildChart(rows,spec,'scatter',{width:640,height:360});const elapsed=performance.now()-started;
  const marks=(svg.match(/data-viz-part="point"/g)||[]).length;
  if(marks>400||!svg.includes('sampled from 20000'))throw Error('Dense scatter preview exceeded its visual budget');
  return `${Math.round(elapsed)} ms to render 20,000 synthetic observations; ${marks} SVG marks; no data uploaded`;
 });
 if(!$('releaseDiagnosticResults'))return;
 lastReleaseDiagnostics={app:'OpenViz Studio',version:'3.6',checkedAt:new Date().toISOString(),origin:location.origin,browser:navigator.userAgent,viewport:{width:innerWidth,height:innerHeight},checks};
 const downloadButton=$('releaseDownloadReport');if(downloadButton)downloadButton.disabled=false;
 results.innerHTML=`<div class="release-check-summary"><strong>${checks.filter(c=>c.pass).length} of ${checks.length} checks passed</strong><p class="muted">Origin: ${E(location.origin)} · ${E(new Date().toLocaleString())}</p></div><div class="release-check-list">${checks.map(c=>`<div class="release-check ${c.pass?'release-pass':'release-fail'}"><span aria-hidden="true">${c.pass?'✓':'!'}</span><div><strong>${E(c.name)}</strong><p>${E(c.summary)}</p></div></div>`).join('')}</div><p class="hint">These checks do not certify PowerPoint fidelity, Firefox/Safari, large-project performance, or long-term backups. Download an .openviz backup for critical work.</p>`;
}
