document.addEventListener('keydown',e=>{const ctrl=e.ctrlKey||e.metaKey;const typing=e.target.matches?.('input,textarea,select,[contenteditable]');if(e.key==='Escape'){closeModal();closeMenus();}if(ctrl&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();}if(ctrl&&e.key.toLowerCase()==='s'){e.preventDefault();if(ui.page==='home')showToast('Open a project to save it.');else persist().then(()=>showToast('Saved locally'));}if(!typing&&ui.page==='visualise'&&ui.annotationSelection.length&&['Delete','Backspace'].includes(e.key)){e.preventDefault();deleteAnnotations();}if(ctrl&&e.altKey&&!typing&&e.key.toLowerCase()==='c'){e.preventDefault();copyAppearance();}if(ctrl&&e.altKey&&!typing&&e.key.toLowerCase()==='v'){e.preventDefault();pasteAppearance();}if(ctrl&&!typing&&e.key.toLowerCase()==='z'){e.preventDefault();runAction('undo',document.body);}if(ctrl&&!typing&&e.key.toLowerCase()==='y'){e.preventDefault();runAction('redo',document.body);}});
// V1.8 keyboard conventions mirror familiar presentation editors.
document.addEventListener('keydown',e=>{
 if(ui.page!=='present'||ui.slideEditingId||e.target.closest?.('input,textarea,select,[contenteditable]'))return;
 const modifier=e.ctrlKey||e.metaKey,ids=slideSelection(),selected=(slide()?.objects||[]).filter(o=>ids.includes(o.id)&&!o.locked);
  if(modifier&&e.key.toLowerCase()==='g'){e.preventDefault();if(e.shiftKey)ungroupSlideSelection();else groupSlideSelection();return;}
 if(modifier&&e.key.toLowerCase()==='a'){
  e.preventDefault();ui.selectedObjectIds=slide()?.objects.filter(o=>!o.hidden).map(o=>o.id)||[];ui.selectedObjectId=ui.selectedObjectIds.at(-1)||null;renderSlideStage();renderSlideInspector();return;
 }
 if(modifier&&e.key.toLowerCase()==='d'&&selected.length){
  e.preventDefault();trackChange();const groupCopies=new Map();const copies=selected.map(o=>{const copy={...structuredClone(o),id:uuid(),x:Math.min(98,o.x+2),y:Math.min(98,o.y+2)};if(copy.groupId){if(!groupCopies.has(copy.groupId))groupCopies.set(copy.groupId,newId('group'));copy.groupId=groupCopies.get(copy.groupId);}return copy;});
  slide().objects.push(...copies);ui.selectedObjectIds=copies.map(o=>o.id);ui.selectedObjectId=ui.selectedObjectIds.at(-1);markDirty();renderSlideStage();renderSlideInspector();return;
 }
 if(!ids.length)return;
 if(['Backspace','Delete'].includes(e.key)){
  e.preventDefault();runAction('delete-object',document.body);return;
 }
 if(e.key.startsWith('Arrow')){
  const canvas=$('slideCanvas'),box=canvas?.getBoundingClientRect();if(!box)return;
  const step=e.shiftKey?10:1,dx=(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0)/box.width*100,dy=(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)/box.height*100;
  e.preventDefault();trackChange();for(const o of selected){o.x=Math.round((o.x+dx)*10)/10;o.y=Math.round((o.y+dy)*10)/10;}
  markDirty();renderSlideStage();renderSlideInspector();
 }
});

