 const id=el.dataset.dashboardFreeId,dash=project.dashboards[0];if(dash.mode!=='free')return;
 ui.dashboardSelectedId=id;document.querySelectorAll('[data-dashboard-free-id]').forEach(v=>v.classList.toggle('selected',v.dataset.dashboardFreeId===id));renderDashboardInspector();
