 const id=el.dataset.slideObject,s=slide(),canvas=$('slideCanvas');if(!s||!canvas||s.objects.find(o=>o.id===id)?.locked)return;
 if(e.shiftKey||e.ctrlKey||e.metaKey){selectSlideObject(id,true);ui.slideSelectionChangedByPointer=true;return;}
 selectSlideObject(id,false);
 const ids=slideSelection(),selected=s.objects.filter(o=>ids.includes(o.id)&&!o.locked),other=s.objects.filter(o=>!ids.includes(o.id)&&!o.hidden);if(!selected.length)return;
 const starting=selected.map(o=>({o,x:o.x,y:o.y})),base=projectSnapshot(project),rect=canvas.getBoundingClientRect(),sx=e.clientX,sy=e.clientY;
 const bounds={x:Math.min(...selected.map(o=>o.x)),y:Math.min(...selected.map(o=>o.y))};
