// V3.7: preview/data studio. UI state is intentionally outside portable project data.
function studioToolbar(){
 const tab=(id,label)=>`<button role="tab" id="studio-tab-${id}" aria-controls="workspaceContent" aria-selected="${ui.studioTab===id}" tabindex="${ui.studioTab===id?0:-1}" class="${ui.studioTab===id?'active':''}" data-action="studio-${id}">${label}</button>`;
 return `<button class="secondary-button button-small v36-mobile-project" data-action="v36-toggle-project" aria-pressed="${ui.studioProjectOpen}" title="Charts, datasets and other workspaces">☰ Project</button><div class="studio-tabs" role="tablist" aria-label="Visualisation editor">${tab('preview','Preview')}${tab('data','Data')}</div><span class="toolbar-rule"></span>${toolbarButton('↶','undo',`aria-label="Undo" title="Undo" ${!undo.length?'disabled':''}`)}${toolbarButton('↷','redo',`aria-label="Redo" title="Redo" ${!redo.length?'disabled':''}`)}<span class="toolbar-spacer"></span>${ui.studioTab==='preview'?`<div class="studio-devices" role="group" aria-label="Preview width">${[['desktop','Desktop'],['tablet','Tablet'],['phone','Phone']].map(([id,label])=>`<button data-action="studio-device" data-id="${id}" aria-pressed="${ui.studioDevice===id}" class="${ui.studioDevice===id?'active':''}">${label}</button>`).join('')}</div>`:toolbarButton('↻ Replace data','refresh-data',!chartDataset()?'disabled':'')}${toolbarButton('Change template','compare-chart',!chart()?'disabled':'')}<button class="v36-mobile-edit secondary-button button-small" data-action="v36-toggle-properties">${ui.rightOpen?'Hide settings':ui.studioTab==='data'?'Column bindings':'Settings'}</button>`;
}
function columnLetter(index){let label='';for(let i=index+1;i>0;i=Math.floor((i-1)/26))label=String.fromCharCode(65+(i-1)%26)+label;return label;}
function propertiesFor(tab,c,d){const saved=ui.inspectorTab;try{ui.inspectorTab=tab;return chartProperties(c,d);}finally{ui.inspectorTab=saved;}}
function studioSections(html,prefix,defaultOpen=false){
 const holder=document.createElement('div');holder.innerHTML=html;
 return [...holder.children].map((section,index)=>{const heading=section.querySelector('h4'),title=heading?.textContent||'Options';heading?.remove();const id=prefix+'-'+index;return `<details class="studio-settings-section" data-studio-section="${id}" ${(ui.studioSections[id]??defaultOpen)?'open':''}><summary>${E(title)}</summary><div class="studio-settings-body">${section.innerHTML}</div></details>`;}).join('');
}
function renderStudioInspector(){
 const root=$('inspectorContent'),c=chart(),d=chartDataset(c);if(!c||!d){root.innerHTML='<p class="hint">Choose a visualisation and dataset to edit its settings.</p>';return;}
 const scroll=root.scrollTop;
 if(c.type==='editorial-table'&&ui.studioTab!=='data'){
  root.innerHTML=`<div class="studio-template-info"><span class="eyebrow">VISUALISATION</span><strong>Editorial table</strong><button class="subtle-button button-small" data-action="compare-chart">Change template →</button></div>`+studioSections(`<section><h4>Table details</h4>${field('Title',input('title',c.title))}${field('Subtitle',input('subtitle',c.subtitle))}${check('showTitle','Show title',c.showTitle)}${check('showSubtitle','Show subtitle',c.showSubtitle)}${field('Source credit',input('sourceNote',c.sourceNote||''))}${field('Description',`<textarea data-setting="altText">${E(c.altText||'')}</textarea>`)}${colorInput('background',c.background,'Background')}${colorInput('textColor',c.textColor,'Text')}${colorInput('color',c.color,'In-cell graphics')}</section>`,'editorial-details',true)+studioSections(tableAppearanceProperties(c,d),'editorial-columns',true);
  root.scrollTop=scroll;return;
 }
 if(ui.studioTab==='data'){
  root.innerHTML=`<div class="studio-inspector-intro"><strong>Connect columns to your chart</strong><p>Choose which fields supply each part of the visualisation. Letters match the data table.</p></div>`+studioSections(propertiesFor('data',c,d),'data-'+c.type,true);
  root.querySelector('[data-setting=datasetId]')?.closest('label')?.remove();root.querySelector('[data-setting=aggregation]')?.closest('label')?.remove();
  const specs=fieldSpecs(c),bindingKeys=FIELD_BINDING_KEYS;root.querySelectorAll('select[data-setting]').forEach(select=>{const key=select.dataset.setting;if(!bindingKeys.includes(key))return;const spec=specs.find(s=>s.key===key);if(!spec){select.closest('label')?.remove();return;}const optional=!spec.required,missing=![...select.options].some(option=>option.value===c[key]);if((optional||missing)&&![...select.options].some(option=>option.value==='')){const option=document.createElement('option');option.value='';option.textContent=optional?'Optional / none':'Choose a column…';select.prepend(option);}select.value=c[key]||'';});
  const columns=datasetFields(d);root.querySelectorAll('select[data-setting]').forEach(select=>{if(['datasetId','type','aggregation','networkLayout','geoView','geoPalette'].includes(select.dataset.setting))return;for(const option of select.options){const index=columns.indexOf(option.value);if(index>=0)option.textContent=columnLetter(index)+' · '+option.textContent;}});
 }else if(ui.chartSelection){root.innerHTML=`<button class="subtle-button studio-back" data-action="clear-chart-selection">← All settings</button>`+selectedElementInspector(c,d);
 }else{
  const presets=BUILTIN_STYLES.slice(0,6);
  let html=`<div class="studio-template-info"><span class="eyebrow">VISUALISATION</span><strong>${E(CHARTS[c.type]?.name||c.type)}</strong><button class="subtle-button button-small" data-action="compare-chart">Change template →</button></div>`;
  if(TIME_TYPES.has(c.type))html+=studioSections(`<section><h4>Time controls</h4>${timeControls(c,d)}</section>`,'time-controls',!!c.timeEnabled);
  html+=studioSections(`<section><h4>Templates & styles</h4><p class="hint">Apply a starting design, then refine each setting below.</p><div class="v36-style-grid">${presets.map(style=>`<button class="v36-style-choice" data-action="v36-apply-style" data-id="${style.id}" title="${E(style.description)}"><span class="v36-style-swatch" style="--swatch-bg:${E(style.properties.background)};--swatch-main:${E(style.properties.color)};--swatch-alt:${E(style.properties.secondary)}"><i></i><i></i><i></i></span><span>${E(style.name)}</span></button>`).join('')}</div><div class="inline-actions"><button class="secondary-button button-small" data-action="open-style-library">All styles / Save style</button><button class="secondary-button button-small" data-action="brand-open">Organisation theme…</button></div>${project.brand?`<p class="hint">Organisation theme: <strong>${E(project.brand.name)}</strong>${chart()?.brand?.id===project.brand.id?' · applied to this chart':' · not applied to this chart'}</p>`:''}</section>`,'presets',true);
  if(c.type==='editorial-table')html+=studioSections(tableAppearanceProperties(c,d),'editorial-table',true);
  if(RESEARCH_TYPES.has(c.type))html+=studioSections(`<section><h4>Template options</h4>${researchControls(c,d)}</section>`,'research-'+c.type,true);if(PRO_TYPES.has(c.type)&&PRO_OPTIONS[c.type])html+=studioSections(`<section><h4>Chart options</h4>${proControls(c)}</section>`,'pro-'+c.type,true);if(['bar','line','area','hbar','dot','scatter','bubble'].includes(c.type)&&!c.timeEnabled)html+=studioSections(`<section><h4>${['line','area'].includes(c.type)?'Reference lines & forecast':'Reference, trend & clusters'}</h4>${referenceControls(c)}</section>`,'reference',false);if(project.team&&teamCfg()){html+=studioSections(`<section><h4>Team comments</h4>${teamCommentsMarkup(c)}</section>`,'team-comments',true);setTimeout(loadTeamComments,0);}html+=studioSections(`<section><h4>What-if parameters</h4>${parameterSlidersForChart(c)}</section>`,'parameters',!!(project.parameters||[]).length);if(labelRulesFor(c.type)&&!c.timeEnabled)html+=studioSections(`<section><h4>Value labels</h4>${labelRuleControls(c)}</section>`,'labels',false);if(DRILL_TYPES.has(c.type))html+=studioSections(`<section><h4>Drill-down (live publications)</h4>${drillControls(c,d)}</section>`,'drill',false);if(HIGHLIGHT_TYPES.has(c.type)&&!c.timeEnabled)html+=studioSections(`<section><h4>Highlights & callouts</h4>${highlightControls(c,d)}</section>`,'highlights',(c.highlights||[]).length>0);
  if(['bar-race','line-race'].includes(c.type))html+=studioSections(`<section><h4>Race appearance</h4>${raceAppearanceControls(c)}</section>`,'race-appearance');
  // Reuse the existing, tested settings builders. Remove irrelevant controls, never chart data.
  const style=document.createElement('div');style.innerHTML=propertiesFor('style',c,d);style.firstElementChild?.remove();
  const typography=style.children[0];typography?.querySelector('h4')?.replaceChildren(document.createTextNode('Header & typography'));
  const detail=style.querySelector('[data-setting="lineWidth"]')?.closest('section');
  if(detail){const allowed=new Set();if(['line','area','slope','parallel','multi-line','multi-area','stacked-area','small-multiples','interval-plot','ecdf'].includes(c.type))allowed.add('lineWidth');if(['line','scatter','bubble','slope','multi-line','multi-area','stacked-area','small-multiples','interval-plot','ecdf'].includes(c.type))allowed.add('pointSize');if(['bar','hbar','stacked-bar'].includes(c.type)){allowed.add('barRadius');allowed.add('barWidthRatio');}detail.querySelectorAll('[data-setting]').forEach(input=>{if(!allowed.has(input.dataset.setting))input.closest('label')?.remove();});if(!allowed.size)detail.remove();}
  const header=style.firstElementChild?.outerHTML||'';style.firstElementChild?.remove();if(detail?.parentElement===style)style.prepend(detail);html+=studioSections(style.innerHTML,'style');
  if(GEO_TYPES.has(c.type))html+=studioSections(geoMapStyling(c),'map');
  if(ADVANCED_TYPES.has(c.type)){const special=document.createElement('div');special.innerHTML=advancedChartProperties(c,d);special.firstElementChild?.remove();if(special.querySelector('input,select'))html+=studioSections(special.innerHTML,'special-'+c.type);}
  const noAxes=['pie','donut','treemap','sunburst','sankey','network','radar','gantt','timeline','parallel','geo-choropleth','geo-symbol','geo-heat','evidence-lanes','change-lens','likert','interval-plot','ecdf','calendar-heatmap','assumption-lens','bar-race','line-race'];
  if(!noAxes.includes(c.type))html+=studioSections(propertiesFor('axes',c,d),'axes');
  if(!GEO_TYPES.has(c.type))html+=studioSections(propertiesFor('labels',c,d),'labels');else html+=studioSections(`<section><h4>Accessible design</h4>${field('Chart description',`<textarea data-setting="altText" rows="4">${E(c.altText||'')}</textarea>`)}${(t=>t?`<div class="auto-description"><p class="hint"><strong>Suggested description</strong> (written from the plotted values; readers using screen readers hear this when the box above is empty)</p><p class="auto-description-text">${E(t)}</p><button type="button" class="secondary-button button-small" data-action="use-auto-description">Use as description</button></div>`:'')(describeChart(d?.rows||[],c))}${field('Source credit',input('sourceNote',c.sourceNote||''))}${check('includeDataTable','Include source-data table in HTML exports',!!c.includeDataTable)}<p class="hint">Includes up to 5,000 source rows from bound columns. Review values before sharing.</p><ul class="quality-checks">${qualityChecks(d.rows,c).map(item=>`<li>${E(item.message)}</li>`).join('')}</ul></section>`,'accessibility');
  html+=studioSections(propertiesFor('layout',c,d),'layout')+studioSections(header,'header')+studioSections(propertiesFor('publication',c,d),'publication');
  html+=studioSections(`<section><h4>Annotations & animation</h4><div class="studio-action-list"><button class="secondary-button" data-action="add-annotation">Add annotation</button><button class="secondary-button" data-action="toggle-chart-layers">Show / hide chart layers</button><button class="secondary-button" data-action="motion-open">Motion timeline</button><button class="secondary-button" data-action="story-open">Open Story Studio</button><button class="secondary-button" data-action="to-compare">Compare chart types</button></div></section>`,'tools');root.innerHTML=html;
 }
 if(EXPANDED_TYPES.has(c.type)&&ui.studioTab==='preview'&&!ui.chartSelection){
  const unsupported=[...(['bar-race','line-race'].includes(c.type)?['showLabels']:[]),'yMin','yMax','tickCount','xLabelRotation','axisLineWidth','axisColor','gridWidth','gridDash','legendPosition','labelColor'];
  if(EXPERIMENTAL_TYPES.has(c.type)||c.type==='small-multiples'||RESEARCH_TYPES.has(c.type)&&c.type!=='ecdf')unsupported.push('showLegend','legendFontSize');
  for(const key of unsupported)root.querySelectorAll(`[data-setting="${key}"]`).forEach(el=>el.closest('label')?.remove());
  const rangeReset=root.querySelector('[data-action=reset-axis-range]');if(c.yMin!=null||c.yMax!=null)rangeReset?.replaceChildren(document.createTextNode('Clear previous axis bounds'));else rangeReset?.remove();
  root.querySelectorAll('.studio-settings-body').forEach(body=>{if(body.querySelector('[data-setting=valueFormat]')&&body.textContent.includes('Numeric scale'))return;if(body.textContent.includes('Leave minimum or maximum')){body.querySelector('.hint')?.remove();body.insertAdjacentHTML('afterbegin','<p class="hint">This template uses an automatic shared scale. Percentage stacks use 0–100%.</p>');}});
 }
 root.scrollTop=scroll;
}
function decorateStudioData(){
 const root=$('workspaceContent'),d=chartDataset();if(!d)return;root.querySelector('.data-layout')?.classList.add('studio-data-layout');
 root.querySelector('.workspace-heading')?.remove();root.querySelector('.dropzone')?.remove();root.querySelector('.data-summary')?.remove();
 const source=root.querySelector('[data-ui="dataset"]')?.closest('.field-row');if(source)source.outerHTML=`<div class="studio-data-source"><label class="field studio-source-picker"><span>Chart data source</span><select id="studioDatasetSource" data-setting="datasetId" aria-describedby="studioSourceHelp">${project.datasets.map(ds=>`<option value="${E(ds.id)}" ${chart()?.datasetId===ds.id?'selected':''}>${E(ds.name)}</option>`).join('')}</select></label><span class="studio-source-help" id="studioSourceHelp">Choose an imported dataset. Review its column connections before applying the switch.</span><span class="toolbar-spacer"></span><button class="secondary-button button-small" data-action="expression">ƒ Calculated field</button><button class="subtle-button button-small" data-page="data">Manage all datasets ↗</button></div>`;
 root.querySelectorAll('.data-table th:not(.data-row-controls) .data-col-heading>.data-col-name').forEach((span,index)=>{const letter=document.createElement('b');letter.className='studio-column-letter';letter.textContent=columnLetter(index);span.prepend(letter);});
 const sourceBar=root.querySelector('.studio-data-source');if(sourceBar)sourceBar.insertAdjacentHTML('afterend',dataGuide(chart(),d));
 renderStudioInspector();
}
document.addEventListener('toggle',event=>{const section=event.target;if(section.matches?.('[data-studio-section]'))ui.studioSections[section.dataset.studioSection]=section.open;},true);
// V3.59: Enter in the command search runs the first matching command.
