document.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.target?.id!=='commandQuery')return;const first=[...document.querySelectorAll('#commandList [data-action]')].find(b=>!b.hidden&&b.style.display!=='none'&&b.offsetParent!==null);if(first){event.preventDefault();first.click();if(document.getElementById('commandQuery'))closeModal();}});
document.addEventListener('keydown',event=>{const tab=event.target.closest?.('.studio-tabs [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?'preview':event.key==='End'?'data':ui.studioTab==='preview'?'data':'preview';runAction('studio-'+next,tab);});

