// V3.8: staged data connections. The project is untouched until a valid review is applied.
let pendingDatasetSwitch=null;
function requirementList(c){return `<ul class="v38-requirements">${fieldSpecs(c).map(spec=>`<li><strong>${E(spec.label)}</strong><span>${E(({number:'Numeric',numbers:'2–8 numeric columns',date:'Date or numeric date','date-only':'ISO date (YYYY-MM-DD)',any:'Column'})[spec.kind])} · ${spec.required?'Required':'Optional'}</span></li>`).join('')}</ul>`;}
function exampleDataTable(type){const example=chartExample(type),cols=getFields(example.rows).slice(0,6);return `<div class="v38-example"><strong>Illustrative data structure${getFields(example.rows).length>6?' · first 6 columns':''}</strong><div class="v38-example-scroll"><table><thead><tr>${cols.map(f=>`<th>${E(f)}</th>`).join('')}</tr></thead><tbody>${example.rows.slice(0,2).map(row=>`<tr>${cols.map(f=>`<td>${E(row[f]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
function dataGuide(c,d){const meta=CATALOGUE.find(m=>m.id===c.type),issues=mappingIssues(c,d);return `<section class="v38-data-guide"><div class="v38-calculation"><strong>How values are calculated</strong><p>${E(calculationSummary(c))}</p>${usesAggregation(c.type)||isRegional(c)?field('Calculation',`<select data-setting="aggregation" aria-label="Chart calculation">${[['sum','Sum'],['average','Average'],['count','Count rows'],['min','Minimum'],['max','Maximum']].filter(([id])=>c.type!=='change-lens'||id!=='count').map(([id,label])=>`<option value="${id}" ${c.aggregation===id?'selected':''}>${label}</option>`).join('')}</select>`):''}</div>${RESEARCH_TYPES.has(c.type)?researchControls(c,d):''}${PRO_TYPES.has(c.type)&&PRO_OPTIONS[c.type]?proControls(c):''}<details><summary>Data requirements & example · ${E(CHARTS[c.type]?.name||c.type)}</summary><p>${E(meta?.use||'')}</p>${requirementList(c)}${exampleDataTable(c.type)}<p class="v38-guidance">${E(alternativeHint(c,d.rows))}</p></details>${issues.length?`<div class="notice" role="status"><strong>Check these connections</strong><ul>${issues.map(issue=>`<li>${E(issue)}</li>`).join('')}</ul></div>`:''}</section>`;}
function requestDatasetSwitch(targetId){const c=chart(),target=project.datasets.find(d=>d.id===targetId);if(!c||!target)return;const {draft,status}=proposeMappings(c,target);pendingDatasetSwitch={projectId:project.id,chartId:c.id,fromId:c.datasetId,toId:target.id,draft,status,sequence:editSequence};renderDatasetSwitch();}
function renderDatasetSwitch(focusKey=null){const state=pendingDatasetSwitch,target=project.datasets.find(d=>d.id===state?.toId),current=project.charts.find(c=>c.id===state?.chartId);if(!state||!target||!current)return;
 const schema=schemaFor(target),issues=mappingIssues(state.draft,target),warnings=issues.length?[]:chartWarnings(target.rows,state.draft);const preview=issues.length?'':`<div class="v38-switch-preview"><strong>Preview with the reviewed columns</strong>${buildChart(target.rows,{...state.draft,showTitle:false,showSubtitle:false},state.draft.type,{width:500,height:280})}</div>`;
 const mapping=fieldSpecs(state.draft).map(spec=>{const previous=current[spec.key],status=state.status[spec.key]||'Choose a column';
 const control=['numbers','columns'].includes(spec.kind)?`<div class="v38-dimension-list">${schema.filter(f=>fieldFits(f,spec)).map(f=>`<label><input type="checkbox" data-switch-dimension="${E(encodeURIComponent(f.name))}" ${(state.draft.parallelFields||[]).includes(f.name)?'checked':''}>${E(f.name)}</label>`).join('')||'<p>No numeric columns available.</p>'}</div>`:`<select data-switch-field="${spec.key}" aria-label="${E(spec.label)}"><option value="">${spec.required?'Choose a column…':'Optional / none'}</option>${schema.filter(f=>fieldFits(f,spec)).map(f=>`<option value="${E(f.name)}" ${state.draft[spec.key]===f.name?'selected':''}>${E(f.name)} · ${E(f.type)}</option>`).join('')}</select>`;
 return `<div class="v38-mapping-row"><div><strong>${E(spec.label)}${spec.required?' *':''}</strong><small>Previously: ${E(Array.isArray(previous)?previous.join(', '):previous||'None')}</small></div><div>${control}<small class="v38-mapping-status">${E(status)}</small></div></div>`;}).join('');
 openModal('Review data connection',`<div id="datasetSwitchReview"><p>Connect <strong>${E(current.title)}</strong> to <strong>${E(target.name)}</strong> (${target.rows.length.toLocaleString()} rows). Review every required connection. Suggestions are starting points, not verified matches.</p>${current.geoTooltipFields?.length?'<p class="notice">Additional tooltip fields will be cleared when switching datasets. Add them again in Tooltip labels & values after reviewing the new data.</p>':''}<div class="v38-mapping-list">${mapping}</div><p class="v38-guidance">Chart titles, annotations and appearance are retained. Check that they still describe the new data. Other charts and both source datasets stay unchanged.</p><div class="v38-switch-status" role="status">${issues.length?`<strong>Complete these connections before applying:</strong><ul>${issues.map(issue=>`<li>${E(issue)}</li>`).join('')}</ul>`:'Required column connections are complete. Review the chart-specific warnings below before applying.'}${warnings.length?`<ul>${warnings.map(w=>`<li>${E(w)}</li>`).join('')}</ul>`:''}</div><p class="v38-guidance">${E(calculationSummary(state.draft))}</p>${preview}<div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="dataset-switch-apply" ${issues.length?'disabled':''}>Apply connection</button></div></div>`,true);
 if(focusKey)document.querySelector(`[data-switch-field="${focusKey}"]`)?.focus();
}
function updateDatasetSwitch(input){const state=pendingDatasetSwitch;if(!state)return;if(input.dataset.switchField){const key=input.dataset.switchField;if(!fieldSpecs(state.draft).some(s=>s.key===key))return;state.draft[key]=input.value;state.status[key]='Chosen by you';renderDatasetSwitch(key);}else{const name=decodeURIComponent(input.dataset.switchDimension),set=new Set(state.draft.parallelFields||[]);if(input.checked)set.add(name);else set.delete(name);state.draft.parallelFields=[...set];state.status.parallelFields='Chosen by you';renderDatasetSwitch();document.querySelector(`[data-switch-dimension="${CSS.escape(input.dataset.switchDimension)}"]`)?.focus();}}
function applyDatasetSwitch(){const state=pendingDatasetSwitch;if(!state||!$('datasetSwitchReview'))return;const current=project.charts.find(c=>c.id===state.chartId),target=project.datasets.find(d=>d.id===state.toId);
 if(project.id!==state.projectId||!current||!target||current.datasetId!==state.fromId||editSequence!==state.sequence){closeModal();pendingDatasetSwitch=null;showToast('The project changed during review. Choose the dataset again to review its current connections.');return;}
 if(mappingIssues(state.draft,target).length){renderDatasetSwitch();return;}
 trackChange();Object.assign(current,state.draft);ui.selectedDatasetId=target.id;ui.selectedChartId=current.id;ui.dataPage=0;ui.selectedDataRows.clear();pendingDatasetSwitch=null;closeModal();markDirty();render();$('studioDatasetSource')?.focus();showToast('Data connection applied · Undo restores the previous connection');
}

function expandedChartProperties(c,d){return `<section class="inspector-group"><h4>${EXPERIMENTAL_TYPES.has(c.type)?'Experimental data connections':RESEARCH_TYPES.has(c.type)?'Template data connections':'Series data connections'}</h4>${fieldSpecs(c).map(spec=>field(spec.label,`<select data-setting="${spec.key}"><option value="">Choose a column…</option>${schemaFor(d).filter(f=>fieldFits(f,spec)).map(f=>`<option value="${E(f.name)}" ${c[spec.key]===f.name?'selected':''}>${E(f.name)}</option>`).join('')}</select>`)).join('')}<p class="hint">${E(calculationSummary(c))}</p>${EXPERIMENTAL_TYPES.has(c.type)?'<p class="notice">Exploratory design using established encodings. Inspect the values and assumptions before interpreting a pattern.</p>':''}</section>`;}
function homeTemplateSection(){const ids=['combo','kpi','editorial-table','bump','waffle','range-plot','line-race','beeswarm'];return `<section class="home-templates" aria-labelledby="homeTemplatesHeading"><div class="section-title"><div><h2 id="homeTemplatesHeading">Start from a template</h2><p class="muted small">${CATALOGUE.filter(c=>c.status==='available').length} chart, map and table templates — each opens with editable example data.</p></div><div class="inline-actions"><button class="secondary-button button-small" data-action="map-library-open">Map library</button><button class="secondary-button button-small" data-action="home-explore-gallery">Browse all templates →</button></div></div><div class="home-template-grid">${ids.map(type=>{const ex=chartExample(type),cfg={...DEFAULT_CHART,...ex,type,showTitle:false,showSubtitle:false,showLegend:true,padding:22};return `<button class="home-template-card" data-action="home-template" data-type="${type}"><span class="home-template-preview" aria-hidden="true" inert>${buildChart(ex.rows,cfg,type,{width:400,height:260})}</span><span class="home-template-caption"><strong>${E(CHARTS[type].name)}</strong><small>${EXPERIMENTAL_TYPES.has(type)?'Experimental · ':''}View template →</small></span></button>`;}).join('')}</div></section>`;}

function researchControls(c,d){
 const choose=(key,label,options,value=c[key])=>field(label,`<select data-setting="${key}">${options.map(([id,name])=>`<option value="${E(id)}" ${String(value)===String(id)?'selected':''}>${E(name)}</option>`).join('')}</select>`);
 if(['bar-race','line-race'].includes(c.type)){const m=raceModel(d.rows,c);return `<div class="research-options">${field(c.type==='line-race'?'Maximum lines by peak (3–15)':'Maximum visible bars (3–15)',input('raceTopN',c.raceTopN||10,'number','min="3" max="15"'))}${field('Milliseconds per period',input('raceStepMs',c.raceStepMs||1600,'number','min="300" max="10000" step="100"'))}${choose('raceIndex','Period for static exports',m.frames.map((f,i)=>[i,f.period]),Math.max(0,Math.min(m.frames.length-1,Number(c.raceIndex)||0)))}${choose('raceMissing','Absent entity–period pairs',[['hide','Hide absent entities'],['zero','Explicitly assume zero']],c.raceMissing||'hide')}<button class="secondary-button" data-action="race-assets-open">Category images, flags & colours…</button>${check('raceLoop','Loop playback',!!c.raceLoop)}${field('Pause before looping (ms)',input('raceLoopPauseMs',c.raceLoopPauseMs??1000,'number','min="0" max="10000" step="100"'))}${c.type==='line-race'?'':check('raceTimeline','Show entity history mini-chart',c.raceTimeline!==false)}${c.type==='line-race'?'':choose('raceTimelineEntity','History entity',[['','Automatic · highest peak'],...m.names.map(name=>[name,name])],c.raceTimelineEntity||'')}${field('Caption for selected static period',`<textarea data-setting="raceCaptionText" rows="3" maxlength="400" placeholder="Describe what happens in this period.">${E(m.frames[Math.max(0,Math.min(m.frames.length-1,Math.floor(Number(c.raceIndex)||0)))]?.caption||'')}</textarea>`)}<p class="hint">Choose a period above to edit its caption. Captions remain active until the next observed period. Loop pauses use real milliseconds, independent of playback speed. ${c.type==='line-race'?'Lines reveal trajectories, keep missing gaps and use numeric/date X spacing. At most 15 entities are selected by peak across all periods.':'History shows one entity, with gaps for missing values; it is omitted when the canvas is too short.'}</p><p class="hint">Fixed scale across all periods; equal playback time steps. Interpolated transitions are not source observations. Numeric/ISO dates sort; other labels use first appearance. Playback is available in Preview and standalone interactive chart HTML; dashboards and stories show the saved period.</p></div>`;}
 if(c.type==='likert')return `<div class="research-options">${field('Response labels, from negative to positive (one per line)',`<textarea data-setting="likertOrder" rows="5">${E(Array.isArray(c.likertOrder)?c.likertOrder.join('\n'):c.likertOrder||DEFAULT_LIKERT_ORDER.join('\n'))}</textarea>`)}${field('Neutral label (blank for an even scale)',input('likertNeutral',c.likertNeutral??'Neutral'))}${choose('likertNeutralMode','Neutral placement',[['split','Centre neutral across zero'],['separate','Show neutral in a separate column']],c.likertNeutralMode||'split')}<p class="hint">Order is explicit. Neutral stays in the denominator; unknown labels and negative counts must be corrected before rendering.</p></div>`;
 if(c.type==='interval-plot')return `<div class="research-options">${field('What the supplied bounds mean',input('intervalLabel',c.intervalLabel||'Supplied interval'))}${field('Reference value (optional)',input('intervalReference',c.intervalReference??'','number','step="any" placeholder="None"'))}<p class="hint">No confidence level is inferred. Reversed bounds are excluded; estimates outside their bounds remain visible.</p></div>`;
 if(c.type==='calendar-heatmap'){const model=calendarModel(d.rows,c);return `<div class="research-options">${choose('calendarYear','Calendar year',[[0,'Automatic — latest year in data'],...model.years.map(y=>[y,String(y)])],c.calendarYear||0)}<p class="hint">ISO calendar date as written; Monday-first weeks. Missing dates are grey, including dates with no valid numeric records.</p></div>`;}
 if(c.type==='assumption-lens')return `<div class="research-options">${choose('assumptionBaseline','Baseline (missing values excluded)',Object.entries(METHODS),c.assumptionBaseline||'average')}${choose('assumptionAlternative','Alternative statistic',Object.entries(METHODS),c.assumptionAlternative||'median')}${choose('assumptionMissing','Alternative missing-data rule',Object.entries(MISSING_POLICIES),c.assumptionMissing||'exclude')}<p class="hint">Both rankings use the same matched groups. Zero filling is a declared assumption, not recovered data. Higher values rank first; ties share average ranks.</p></div>`;
 return `<p class="hint">Exact ECDF: each jump includes all ties. No fitted distribution or confidence band is added. Filter groups above 5,000 distinct values for an exact, bounded-size display.</p>`;
}

function publishQualityMarkup(){const ids=publishUI.kind==='chart'?[publishUI.assetId]:publishUI.kind==='dashboard'?project.dashboards.find(d=>d.id===publishUI.assetId)?.chartIds||[]:project.stories.find(s=>s.id===publishUI.assetId)?.scenes?.map(s=>s.chartId)||[];const charts=[...new Set(ids)].map(id=>project.charts.find(c=>c.id===id)).filter(Boolean);const checks=charts.flatMap(c=>{const d=chartDataset(c);return d?[...mappingIssues(c,d),...chartWarnings(d.rows,c),...qualityChecks(d.rows,c).map(x=>x.message)].map(message=>({title:c.title,message})): [{title:c.title,message:'Missing dataset.'}];});return `<details class="publish-quality"><summary>Publication checks · ${checks.length} review items</summary><p class="hint">Guidance, not accessibility certification. Review the preview at all three sizes.</p><ul>${checks.map(c=>`<li><strong>${E(c.title)}</strong>: ${E(c.message)}</li>`).join('')||'<li>No automatic issues found. Inspect the final output.</li>'}</ul></details>`;}

function studioPreviewSize(c){return ui.studioDevice==='phone'?{width:360,height:c.height}:ui.studioDevice==='tablet'?{width:700,height:c.height}:{};}

function editorChartContent(d,c){if(c.type==='editorial-table')return '<style>'+editorialTableCss+'</style>'+editorialTableMarkup(d.rows,c,true);if(ui.mapCanvasEdit&&GEO_TYPES.has(c.type)&&c.type!=='geo-heat')c={...c,geoShowLabels:true};if(c.timeEnabled&&TIME_TYPES.has(c.type))return timePlayerMarkup(d.rows,c,(rows,cfg)=>chartPreview(rows,cfg,cfg.type,studioPreviewSize(cfg)),{editor:true});return ['bar-race','line-race'].includes(c.type)?racePlayerMarkup(d.rows,c,(rows,cfg)=>chartPreview(rows,cfg,cfg.type,studioPreviewSize(cfg)),{editor:true}):chartPreview(d.rows,c,c.type,studioPreviewSize(c));}
function disposeEditorRace(){for(const player of installEditorRace.players||[])player.dispose();installEditorRace.players=[];}
function installEditorRace(){installEditorRace.players=[...(installEditorRace.players||[]),...installRacePlayers($('liveChartSvg')||document.createElement('div')),...installTimePlayers($('liveChartSvg')||document.createElement('div'))];}
document.addEventListener('time-capture',event=>{if(!chart()?.timeEnabled)return;updateChartSetting('timeIndex',event.detail.index,true);render();showToast('Period saved for static exports');});
document.addEventListener('race-capture',event=>{if(!['bar-race','line-race'].includes(chart()?.type))return;updateChartSetting('raceIndex',event.detail.index,true);render();showToast('Period saved for static exports');});

function raceExportOptions(){return {format:$('raceExportFormat')?.value||'gif',startIndex:Number($('raceExportStart')?.value),endIndex:Number($('raceExportEnd')?.value),speed:Number($('raceExportSpeed')?.value)||1,longEdge:Number($('raceExportSize')?.value)||560,fps:Number($('raceExportFps')?.value)||12,endHoldMs:Number($('raceExportHold')?.value)||0,loop:!!$('raceExportLoop')?.checked};}
function refreshRaceExportFormat(){const video=$('raceExportFormat')?.value==='video',size=$('raceExportSize');if(size)size.innerHTML=(video?[720,960,1280]:[480,560,720]).map(n=>`<option value="${n}" ${n===(video?960:560)?'selected':''}>${n} px longest edge</option>`).join('');if($('raceExportFps'))$('raceExportFps').value=video?'24':'12';if($('raceExportLoop'))$('raceExportLoop').disabled=video;}
function refreshRaceExportEstimate(){const node=$('raceExportEstimate'),start=$('raceExportStartJob');if(!node||!start)return;try{const c=project.charts.find(c=>c.id===raceExportContext?.chartId),d=c&&chartDataset(c);if(!c||!d)throw Error('The source chart is unavailable.');const options=raceExportOptions();if(options.format==='video'&&!raceVideoType())throw Error('Video recording is unavailable here. Choose GIF or interactive HTML.');const p=raceExportPlan(d.rows,c,options);node.textContent=`${p.periodStart} → ${p.periodEnd} · ${p.width} × ${p.height} · ${(p.durationMs/1000).toFixed(2)} seconds, including ${(p.endHoldMs/1000).toFixed(2)}s final hold. `+(p.format==='gif'?`${p.samples.length} frames · approximately ${p.effectiveFps.toFixed(1)} fps during movement · ${(p.frameBufferBytes/1048576).toFixed(1)} MB of frame buffers. Frame rate may be reduced to preserve duration within the 96 MB buffer budget.${p.effectiveFps<6?' Low frame rate: shorten the range or reduce output size for smoother motion.':''}`:`Target ${p.fps} fps. Recording runs in real time; device speed can reduce the delivered frame rate. Keep this tab visible.`);start.disabled=!!activeRaceExport;}catch(error){node.textContent=error.message;start.disabled=true;}}
function openRaceExportDialog(){if(activeRaceExport){showToast('Wait for the current export to finish cancelling.');return;}const c=chart(),d=c&&chartDataset(c);if(!['bar-race','line-race'].includes(c?.type)||!d){showToast('Select a bar or line chart race first.');return;}const m=raceModel(d.rows,c);if(m.errors.length||m.frames.length<2){showToast(m.errors[0]||'A race needs at least two periods.');return;}(installEditorRace.players||[]).forEach(p=>p.pause());raceExportContext={chartId:c.id};lastRaceExport=null;const select=(id,label,options)=>`<label class="field"><span>${label}</span><select id="${id}" data-race-export-setting>${options}</select></label>`,periods=(selected)=>m.frames.map((f,i)=>`<option value="${i}" ${i===selected?'selected':''}>${E(f.period)}</option>`).join('');
openModal('Export race animation',`<p class="muted">Export changing values and positions, captions and the history chart. The selected range gets its own fixed scale and history. Source data and the saved chart stay unchanged.</p><div class="race-export-grid">${select('raceExportFormat','Format','<option value="gif">Animated GIF</option><option value="video" '+(!raceVideoType()?'disabled':'')+'>Browser video ('+(raceVideoType()?.includes('mp4')?'MP4':'WebM')+')</option>')}${select('raceExportStart','First period',periods(0))}${select('raceExportEnd','Last period',periods(m.frames.length-1))}${select('raceExportSpeed','Playback speed','<option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option>')}${select('raceExportSize','Output size','')}${select('raceExportFps','Target frame rate',[6,12,18,24,30].map(n=>`<option value="${n}" ${n===12?'selected':''}>${n} fps</option>`).join(''))}<label class="field"><span>Final hold (ms)</span><input id="raceExportHold" data-race-export-setting type="number" min="0" max="10000" step="100" value="${Math.max(0,Math.min(10000,Number(c.raceLoopPauseMs??1000)||0))}"></label><label class="checkbox-field"><input id="raceExportLoop" data-race-export-setting type="checkbox" checked> Loop GIF</label></div><p class="hint">GIF: up to 60 seconds and 220 frames. Video: up to 90 seconds and 64 MB. Output preserves the chart aspect ratio. A zero final hold still includes at least one output frame. Long captions retain the chart's two-line visual limit.</p><p class="notice" id="raceExportEstimate"></p><div class="export-job"><strong id="raceExportPhase">Ready to export</strong><progress id="raceExportProgress" max="100" value="0"></progress><p id="raceExportStatus" role="status">Everything renders locally. Video is stopped if the tab becomes hidden.</p></div><div class="export-dialog-actions"><button class="secondary-button" data-action="race-export-cancel" id="raceExportCancel">Close</button><button class="secondary-button" data-action="race-export-again" id="raceExportAgain" hidden>Download again</button><button class="primary" data-action="race-export-start" id="raceExportStartJob">Export animation</button></div>`,true);refreshRaceExportFormat();refreshRaceExportEstimate();}
async function performRaceExport(){if(activeRaceExport)return;const c=project.charts.find(c=>c.id===raceExportContext?.chartId),d=c&&chartDataset(c);if(!c||!d)return;const options=raceExportOptions();try{raceExportPlan(d.rows,c,options);}catch(error){showToast(error.message);return;}const cfg=structuredClone(c),rows=structuredClone(d.rows),controller=new AbortController();activeRaceExport=controller;lastRaceExport=null;const phase=text=>{if($('raceExportPhase'))$('raceExportPhase').textContent=text;},progress=p=>{if($('raceExportProgress'))$('raceExportProgress').value=Math.round(p*100);};document.querySelectorAll('[data-race-export-setting]').forEach(el=>el.disabled=true);$('raceExportStartJob').disabled=true;$('raceExportAgain').hidden=true;$('raceExportCancel').textContent='Cancel export';
try{const output=await (options.format==='video'?exportRaceVideo:exportRaceGif)(rows,cfg,{...options,signal:controller.signal,onProgress:progress,onStage:phase});if(controller.signal.aborted)return;const base=String(cfg.title||'race').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'race',name=base+'-race.'+output.extension;lastRaceExport={blob:output.blob,name};download(name,output.blob);phase('Export complete');progress(1);if($('raceExportStatus'))$('raceExportStatus').textContent=`${name} · ${(output.blob.size/1048576).toFixed(2)} MB · downloaded`;if($('raceExportAgain'))$('raceExportAgain').hidden=false;}
catch(error){phase(error.name==='AbortError'?'Export cancelled':'Export failed');if($('raceExportStatus'))$('raceExportStatus').textContent=error.name==='AbortError'?'No file was downloaded.':error.message;}
finally{activeRaceExport=null;document.querySelectorAll('[data-race-export-setting]').forEach(el=>el.disabled=false);if($('raceExportCancel'))$('raceExportCancel').textContent='Close';if($('raceExportLoop'))$('raceExportLoop').disabled=$('raceExportFormat')?.value==='video';refreshRaceExportEstimate();}}

function raceAppearanceControls(c){if(c.type==='line-race')return `<button class="secondary-button" data-action="race-assets-open">Category images, flags & colours…</button>${check('raceShowImages','Show endpoint images',c.raceShowImages!==false)}${check('raceValueLabels','Show endpoint values',c.raceValueLabels!==false)}${field('Line width',input('lineWidth',c.lineWidth||3,'number','min="1" max="8"'))}<p class="hint">Endpoint images retain their full proportions. Lines and point observations share one scale; labels are spaced independently of their values.</p>`;const choose=(key,label,values,value)=>field(label,`<select data-setting="${key}">${values.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${name}</option>`).join('')}</select>`);return `<button class="secondary-button" data-action="race-assets-open">Category images, flags & colours…</button>${check('raceShowImages','Show category images',c.raceShowImages!==false)}${choose('raceImagePosition','Image position',[['before-label','Beside category label'],['bar-end','At end of bar']],c.raceImagePosition||'before-label')}${choose('raceImageShape','Image shape',[['contain','Contain full image / flag'],['circle','Circle crop']],c.raceImageShape||'contain')}${field('Image size (px)',input('raceImageSize',c.raceImageSize??24,'number','min="14" max="36"'))}${field('Bar roundness (px)',input('raceBarRoundness',c.raceBarRoundness??2,'number','min="0" max="20"'))}${field('Bar opacity',input('raceBarOpacity',c.raceBarOpacity??1,'number','min="0.2" max="1" step="0.05"'))}${field('Row fill (smaller = more space)',input('raceRowSpacing',c.raceRowSpacing??.66,'number','min="0.4" max="0.85" step="0.05"'))}${field('Category / value label size (px)',input('raceLabelSize',c.raceLabelSize??11,'number','min="9" max="18"'))}${check('raceValueLabels','Show numeric value labels',c.raceValueLabels!==false)}<p class="hint">Image size adapts to the row height. Circle crop can trim flag details; choose Contain to show the entire flag. Large labels/images may need a wider or taller canvas.</p>`;}
function raceAssetContext(){const c=project.charts.find(c=>c.id===raceAssetsContext?.chartId),d=c&&chartDataset(c);return c&&d&&project.id===raceAssetsContext.projectId?{c,d,m:raceModel(d.rows,c)}:null;}
function openRaceAssets(){const c=chart(),d=c&&chartDataset(c);if(!['bar-race','line-race'].includes(c?.type)||!d)return;const m=raceModel(d.rows,c);if(!m.names.length){showToast('Connect an entity/category column first.');return;}(installEditorRace.players||[]).forEach(p=>p.pause());raceAssetsContext={chartId:c.id,projectId:project.id,entity:m.names[0]};renderRaceAssets();}
function renderRaceAssets(){const context=raceAssetContext();if(!context)return;raceAssetsContext.viewId=newId('assetview');const {c,m}=context;if(!m.names.includes(raceAssetsContext.entity))raceAssetsContext.entity=m.names[0]||'';const name=raceAssetsContext.entity,entry=Object.hasOwn(c.raceAssets||{},name)?c.raceAssets[name]:null,asset=resolveRaceAsset(entry),set=raceAssetSet(c),stale=Object.keys(c.raceAssets||{}).filter(k=>!m.names.includes(k)).length;openModal('Category images, flags & colours',`<p class="muted">Assign a bundled flag or upload a local image for each category. Images are embedded in the project and exported files; no image service is contacted.</p><div class="race-assets-layout"><div><label class="field"><span>Category</span><select id="raceAssetEntity">${m.names.map(n=>`<option value="${E(n)}" ${n===name?'selected':''}>${E(n)}</option>`).join('')}</select></label><div class="race-asset-preview">${asset?`<img src="${E(asset.data)}" alt="Image for ${E(name)}"><span>${E(asset.kind==='flag'?asset.code+' flag':asset.label)}</span>`:'<span>No image assigned</span>'}</div><button class="secondary-button" data-action="race-asset-remove" ${Object.hasOwn(c.raceAssets||{},name)?'':'disabled'}>Remove image</button></div><div><label class="field"><span>Bundled flag</span><select id="raceAssetFlag">${flagChoices().map(f=>`<option value="${f.code}" ${f.code===(asset?.code||'NZ')?'selected':''}>${E(f.label)} · ${f.code}</option>`).join('')}</select></label><button class="primary" data-action="race-asset-flag">Assign flag</button><label class="field" style="margin-top:16px"><span>Upload logo or image</span><input id="raceAssetFile" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="hint" id="raceAssetStatus">PNG/JPEG/WebP up to 5 MiB; resized to at most 128 × 128 and embedded as PNG. No SVG or remote URLs.</p><label class="field"><span>Bar colour for ${E(name)}</span><input id="raceAssetColour" type="color" value="${E(raceCategoryColour(name,c))}"></label><div class="inline-actions"><button class="secondary-button" data-action="race-asset-colour">Apply colour</button><button class="secondary-button" data-action="race-asset-colour-reset">Reset colour</button></div></div></div><p class="hint">${set.assets.size} valid assignments · ${(set.bytes/1024).toFixed(1)} KiB of custom images / 2 MiB budget · ${stale} unused assignments. ${set.invalid?set.invalid+' invalid assignments are ignored. ':''}${set.overBudget?'Custom images are hidden because the budget is exceeded.':''} Changes support Undo after closing this window.</p><div class="inline-actions"><button class="secondary-button" data-action="race-asset-auto">Assign recognized country flags</button><button class="secondary-button" data-action="race-asset-prune" ${stale?'':'disabled'}>Remove unused assignments</button></div><p class="hint">Automatic flags use exact English country/territory names or two-letter codes, plus a small set of common aliases. Existing assignments are kept. Review the result. Flags: flag-icons 7.6.0, MIT; licence included with OpenViz.</p>`,true);}
