function setRaceEntityAsset(entry){const context=raceAssetContext();if(!context)return;try{const map=assignRaceAsset(context.c,raceAssetsContext.entity,entry);trackChange();context.c.raceAssets=map;refreshRaceAssetViews();return true;}catch(error){if($('raceAssetStatus'))$('raceAssetStatus').textContent=error.message;showToast(error.message);return false;}}
async function uploadRaceAsset(file){if(!file)return;const snapshot={...raceAssetsContext};if($('raceAssetStatus'))$('raceAssetStatus').textContent='Reading and resizing image locally…';const asset=await importRaceImage(file);if(!raceAssetsContext||project.id!==snapshot.projectId||raceAssetsContext.chartId!==snapshot.chartId||raceAssetsContext.entity!==snapshot.entity||raceAssetsContext.viewId!==snapshot.viewId||!$('raceAssetFile')){showToast('Image selection changed; choose the image again.');return;}if(setRaceEntityAsset(asset))showToast('Image embedded in the project');}
function autoRaceFlags(){const context=raceAssetContext();if(!context)return;try{const {map,count}=assignRecognizedFlags(context.c,context.m.names);if(!count){showToast('No unassigned categories matched exact country names or codes.');return;}trackChange();context.c.raceAssets=map;refreshRaceAssetViews();showToast(count+' flags assigned; review each category.');}catch(error){showToast(error.message);}}
function pruneRaceAssets(){const context=raceAssetContext();if(!context)return;const entries=Object.entries(context.c.raceAssets||{}).filter(([name])=>context.m.names.includes(name));if(entries.length===Object.keys(context.c.raceAssets||{}).length)return;trackChange();context.c.raceAssets=Object.fromEntries(entries);refreshRaceAssetViews();}
function setRaceEntityColour(reset){const context=raceAssetContext();if(!context)return;const value=$('raceAssetColour')?.value;if(!reset&&!/^#[0-9a-f]{6}$/i.test(value||''))return;trackChange();const colours={...(context.c.pointColors||{})};if(reset)delete colours[raceAssetsContext.entity];else Object.defineProperty(colours,raceAssetsContext.entity,{value,enumerable:true,writable:true,configurable:true});context.c.pointColors=colours;refreshRaceAssetViews();}

function timeControls(c,d){const m=timeModel(d.rows,c),points=POINT_TIME_TYPES.has(c.type)&&!isRegional(c),fieldSelect=(key,blank,exclude)=>`<select data-setting="${key}"><option value="">${blank}</option>${getFields(d.rows).filter(f=>!exclude.filter(Boolean).includes(f)).map(f=>`<option value="${E(f)}" ${c[key]===f?'selected':''}>${E(f)}</option>`).join('')}</select>`;return `<button class="secondary-button" data-action="time-example">Try an editable time example</button><button class="secondary-button" data-action="snapshot-export-open" ${c.timeEnabled?'':'disabled'}>Export snapshots as GIF / video…</button>${check('timeEnabled','Enable time snapshots',!!c.timeEnabled)}${field('Time / period column',fieldSelect('timeField','Choose a separate column…',[c.x,c.y,...(['heatmap','multi-line','multi-area','stacked-area','small-multiples','stacked-bar','stacked-hbar','grouped-bar','grouped-hbar','percent-bar','percent-hbar'].includes(c.type)?[c.seriesField]:[]),...(c.type==='bubble'?[c.bubbleSizeField]:[]),...(c.type==='geo-symbol'&&!isRegional(c)?[c.geoLatField,c.geoLonField]:[]),...(c.type==='geo-route'?[c.seriesField,c.geoLatField,c.geoLonField,c.geoToLatField,c.geoToLonField,...((!c.routeAggregation||c.routeAggregation==='rows')?[c.timeEntityField]:[])]:[]),...(points?[c.timeEntityField]:[])]))}${c.type==='geo-route'&&(!c.routeAggregation||c.routeAggregation==='rows')?field('Route ID (optional)',fieldSelect('timeEntityField','Use exact directed coordinate/label pair',[c.timeField,c.x,c.seriesField,c.y,c.geoLatField,c.geoLonField,c.geoToLatField,c.geoToLonField])):''}${points?field('Entity ID / name',fieldSelect('timeEntityField',c.type==='geo-symbol'?'Use place / country field':'Choose a stable entity column…',[c.timeField,c.y,...(c.type==='geo-symbol'?[c.geoLatField,c.geoLonField]:[c.x,c.bubbleSizeField])])):''}${field('Period for static exports',`<select data-setting="timeIndex">${m.frames.map((f,i)=>`<option value="${i}" ${i===Math.max(0,Math.min(m.frames.length-1,Math.floor(Number(c.timeIndex)||0)))?'selected':''}>${E(f.period)}</option>`).join('')}</select>`)}${field('Milliseconds per period',input('raceStepMs',c.raceStepMs||1600,'number','min="300" max="10000" step="100"'))}${check('raceLoop','Loop playback',!!c.raceLoop)}${field('Pause before looping (ms)',input('raceLoopPauseMs',c.raceLoopPauseMs??1000,'number','min="0" max="10000" step="100"'))}<p class="hint">Each period is a separate snapshot. ${c.type==='stacked-area'?'Stack nonnegative components; missing components break their layer and layers above.':c.type==='small-multiples'?'Compare fixed series panels with shared X/Y scales.':c.type==='multi-area'?'Nonnegative areas overlap from zero; they are not stacked. Negative source measures reject playback (Count ignores measures). Full X/Y domains and series colours stay fixed. Known missing observations break fills and outlines; isolated points have no invented area. Filtered outside-range values break fills/lines with disclosed boundary markers.':c.type==='multi-line'?'Use a separate snapshot period and X dimension. X/Y domains and series colours stay fixed. Numeric/ISO date-only X values retain spacing; other labels use source order. Known missing X/series cells break lines; zero stays a measured point. Explicit missing-measure rows keep known X positions. Manual bounds are overridden; filtered outside-range points break lines with disclosed boundary markers.':c.type==='stacked-hbar'?'Positive/negative aggregates stack separately. Full timeline stack totals set fixed bounds; category/series slots, colours, legend and label margins stay fixed. Missing cells are absent; zero has a boundary marker. Filtered over-range totals are clipped and disclosed, with original values retained. Manual bounds are overridden.': ['percent-bar','percent-hbar'].includes(c.type)?'Normalize available category/period aggregates to a fixed 0–100% scale. Negative source measures reject playback (Count ignores measures). Missing series are omitted; zero totals have undefined shares, distinct from no data. Slots, colours and horizontal margins stay fixed. Details retain values, totals and missing counts. Manual bounds are overridden.': ['grouped-bar','grouped-hbar'].includes(c.type)?'Category/series cells aggregate independently per period. Slots, colours and individual-cell value scales stay fixed. Missing cells are absent; zero has a baseline marker. Horizontal label margins use all periods. Fixed bounds override manual axes; per-cell colours override series colour.':c.type==='stacked-bar'?'Series aggregate independently within each period. Positive/negative aggregates stack separately; category positions, series order/colours and total value scale stay fixed; timeline limits override manual axis bounds. Missing combinations are omitted; zero has no area but retains details. Non-Sum/Count stack heights combine aggregates: check that this is meaningful. Per-cell colours override series colour.':c.type==='heatmap'?'Repeated cells aggregate within each period. Row/column positions and a zero-anchored colour range stay fixed across the timeline. Missing cells are grey; zero remains a numeric value. Per-cell colour overrides bypass the scale.':c.type==='geo-route'?'Routes are grouped independently per period. Blank route ID uses the exact directed pair; repeated row identities in a period block playback. Supply distinct IDs for separate observations or choose a grouping mode. Absent connections disappear; map framing and width scales stay fixed. Shared width maximum overrides the automatic timeline maximum.':isRegional(c)&&c.type==='geo-symbol'?'Regional records are aggregated per period. Area is proportional to the non-negative aggregate, with a fixed timeline maximum. Zero has no area; missing regions have no circle.':points?'Entity colours stay stable; use one record per entity/period. Missing IDs are excluded; duplicates block playback. X/Y ranges and bubble/symbol size scales stay fixed.':c.type==='geo-choropleth'?'Countries use one fixed colour range of per-period aggregates. Missing countries remain unshaded.':'The value scale stays fixed; missing categories are omitted.'} ${c.type.startsWith('geo-')?'Map framing, including Fit, is fixed across the whole timeline. ':''}No interpolation or carry-forward. ${['geo-route','heatmap','multi-line','multi-area','stacked-area','small-multiples','stacked-bar','stacked-hbar','grouped-bar','grouped-hbar','percent-bar','percent-hbar'].includes(c.type)?'':'Fixed timeline scales override manual axis bounds and minimum circle radius. '}Playback does not change the saved period. Interactive chart HTML retains controls; dashboard/story/static output uses the saved period. Limits: 60 periods, 30,000 rows, ${c.type==='small-multiples'?'60 X positions × 8 fixed facets across the timeline, ':['multi-line','multi-area','stacked-area'].includes(c.type)?'60 X positions × 10 series across the timeline, ':['grouped-bar','grouped-hbar','percent-bar','percent-hbar','stacked-hbar'].includes(c.type)?'32 categories × 10 series across the timeline, ':c.type==='stacked-bar'?'32 categories × 10 series across the timeline, ':c.type==='heatmap'?'32 columns × 16 rows across the timeline, ':c.type==='geo-route'?'500 connections per period, ':points?'400 valid points per period, ':''}6 MiB playback markup. Snapshot GIF/video playback export is not included.</p>${c.timeEnabled&&m.errors.length?`<p class="hint" role="status">${E(m.errors[0])}</p>`:''}`;}

function addTimeExample(){const type=chart()?.type;if(!TIME_TYPES.has(type))return;const ex=timeExample(type),now=new Date().toISOString(),datasetId=newId('dataset'),id=newId('chart');trackChange();project.datasets.push({id:datasetId,name:CHARTS[type].name+' · illustrative time example',rows:structuredClone(ex.rows),rawRows:structuredClone(ex.rows),calculations:[],source:'OpenViz illustrative time example',updatedAt:now,log:[{time:now,summary:'Created built-in illustrative time dataset'}]});project.charts.push({...structuredClone(DEFAULT_CHART),...ex.settings,id,datasetId});ui.selectedChartId=id;ui.selectedDatasetId=datasetId;ui.chartSelection=null;ui.inspectorTab='style';ui.studioTab='preview';ui.page='visualise';markDirty();render();showToast('Editable time example created · values and locations are illustrative');}

