function settleStoryView(){const st=story(),sc=storyScene(),entry=storyLayout(st).scenes.find(e=>e.scene.id===sc?.id);if(entry)storyUI.ms=Math.min(entry.end,entry.start+Math.max(entry.overlap,sc.transition==='state'?0:sc.animationMs||0));markDirty();render();}
function captureStoryView(){const sc=storyScene(),c=project.charts.find(c=>c.id===sc?.chartId),d=c&&chartDataset(c);if(!c||!d)return;try{const state=captureSceneState(d.rows,c);stopStory();trackChange();sc.state=state;settleStoryView();showToast('Scene view saved · linked chart and source data unchanged');}catch(e){showToast(e.message);}}
function clearStoryView(){const sc=storyScene();if(!sc?.state)return;stopStory();trackChange();sc.state=null;settleStoryView();showToast('Scene follows the linked chart again · Undo restores its saved view');}
function changeStoryView(key,value){const sc=storyScene();if(!sc?.state)return;const state=normalizeSceneState(sc.state);if(state.error)return;if(key==='period'){const c=project.charts.find(c=>c.id===sc.chartId);state.period={kind:['bar-race','line-race'].includes(c?.type)?'race':'time',label:String(value)};}else if(['title','subtitle'].includes(key))state.settings[key]=String(value).slice(0,1000);else if(['yMin','yMax'].includes(key)){if(value!==''&&!Number.isFinite(Number(value)))return;state.settings[key]=value===''?null:Number(value);}else if(key==='geoView'){if(!Object.hasOwn(GEO_VIEWS,value))return;state.settings.geoView=value;}else return;stopStory();trackChange();sc.state=normalizeSceneState(state);settleStoryView();}
function storyViewControls(sc){const c=project.charts.find(c=>c.id===sc.chartId),d=c&&chartDataset(c),state=normalizeSceneState(sc.state);if(!c||!d)return '<div class="inspector-group"><p class="notice">Source chart unavailable.</p></div>';const resolved=resolveSceneView(project,sc),cfg={...c,...state?.settings},select=(key,label,options,value)=>field(label,`<select data-story-view="${key}">${options.map(([v,n])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(n)}</option>`).join('')}</select>`);let controls='';
 if(state&&!state.error){controls+=field('Scene chart title',`<input data-story-view="title" maxlength="1000" value="${E(cfg.title)}">`)+field('Scene chart subtitle',`<input data-story-view="subtitle" maxlength="1000" value="${E(cfg.subtitle)}">`);const race=['bar-race','line-race'].includes(c.type),timed=cfg.timeEnabled&&TIME_TYPES.has(c.type);if(race||timed){const m=race?raceModel(d.rows,cfg):timeModel(d.rows,cfg);controls+=select('period','Saved observed period',m.frames.map(f=>[f.period,f.period]),state.period?.label||m.frames[0]?.period);}
 if(['bar','hbar','dot','scatter','bubble','line','area','multi-line'].includes(c.type)&&!timed)controls+=`<div class="field-row">${field('Y / value minimum',`<input data-story-view="yMin" type="number" step="any" placeholder="Auto" value="${cfg.yMin??''}">`)}${field('Y / value maximum',`<input data-story-view="yMax" type="number" step="any" placeholder="Auto" value="${cfg.yMax??''}">`)}</div>`;
 if(GEO_TYPES.has(c.type)&&!isRegional(c))controls+=select('geoView','Scene map view',Object.keys(GEO_VIEWS).map(v=>[v,v]),cfg.geoView||'world');controls+=`<button class="secondary-button" data-action="story-view-filter">${state.filter?'Edit scene data filter':'Filter this scene’s data…'}</button>${state.filter?`<p class="hint">${state.filter.values.length} selected values · column role: ${E(state.filter.role)}</p><button class="subtle-button" data-action="story-filter-clear">Clear scene filter</button>`:''}`;}
 const st=story(),index=st.scenes.indexOf(sc),prev=st.scenes[index-1];let transition='';if(sc.transition==='state'){const a=prev&&sceneSource(storyFrameSources,prev,index-1),b=sceneSource(storyFrameSources,sc,index),check=a&&b?stateTransitionCheck(a,b,normalizeScene(prev),normalizeScene(sc)):{ok:false,reason:'Matching marks needs a previous scene.'};transition=`<p class="${check.ok?'hint':'notice'}" role="status">${E(check.ok?'Matching marks available. Marks with missing IDs fade in or out.':'Crossfade fallback: '+check.reason)}</p><p class="hint">Matching-mark scenes show complete views; their entry layer animation is skipped. Interpolated geometry is a visual transition, not a new observation.</p>`;}
 return `<div class="inspector-group story-view-controls"><h4>Scene view · ${state?'Saved':'Linked'}</h4><p class="hint">${state?'View settings, filters and the named period are kept for this scene. Data, calculations, field mappings and image assets remain linked. Replacing the view resets its filter.':'This scene follows the original chart’s current settings. Save a view to change it independently.'}</p>${resolved.error?`<p class="notice" role="status">${E(resolved.error)} Exports are blocked until this is resolved.</p>`:''}<button class="secondary-button" data-action="story-view-capture">${state?'Replace view from linked chart':'Save current chart view'}</button>${state?'<button class="subtle-button" data-action="story-view-live">Use linked chart view</button>':''}${controls}${transition}<button class="subtle-button" data-action="story-view-example">Try saved-view example</button><button class="subtle-button" data-action="story-scroll-example">Try scroll story</button></div>`;
}
let storyFilterContext=null;
function openStoryFilter(){const sc=storyScene(),c=project.charts.find(c=>c.id===sc?.chartId),d=c&&chartDataset(c);if(!sc?.state||!c||!d)return;const roles=['x','seriesField','timeEntityField'].filter(role=>c[role]&&d.rows.some(r=>Object.hasOwn(r,c[role]))),role=sc.state.filter?.role||(['bar-race','line-race'].includes(c.type)||SERIES_TYPES.has(c.type)?'seriesField':c.timeEntityField?'timeEntityField':'x');storyFilterContext={projectId:project.id,storyId:story().id,sceneId:sc.id,chartId:c.id,stateRef:sc.state,rowsRef:d.rows,bindings:JSON.stringify([c.x,c.seriesField,c.timeEntityField]),role:roles.includes(role)?role:roles[0],selected:new Set(sc.state.filter?.values||[]),initial:!sc.state.filter};renderStoryFilter();}
function renderStoryFilter(){const ctx=storyFilterContext,sc=storyScene(),c=project.charts.find(c=>c.id===ctx?.chartId),d=c&&chartDataset(c);if(!ctx||!sc||!d)return;const roles=['x','seriesField','timeEntityField'].filter(r=>c[r]&&d.rows.some(row=>Object.hasOwn(row,c[r]))),values=[...new Set(d.rows.map(row=>String(row[c[ctx.role]]??'')))],tooMany=values.length>100;if(ctx.initial){ctx.selected=new Set(values);ctx.initial=false;}openModal('Filter this scene',`<p>The source dataset and other scenes stay unchanged. The saved filter follows the mapped column role when columns are renamed.</p>${field('Filter column',`<select id="storyFilterRole">${roles.map(r=>`<option value="${r}" ${ctx.role===r?'selected':''}>${E(c[r])} · ${E(r)}</option>`).join('')}</select>`)}${tooMany?'<p class="notice">More than 100 distinct values. Filter the source before using a scene filter.</p>':`<div class="story-filter-values">${values.map(v=>`<label><input type="checkbox" data-story-filter-value="${E(encodeURIComponent(v))}" ${ctx.selected.has(v)?'checked':''}> ${E(v||'(blank)')}</label>`).join('')}</div>`}<p class="hint" data-story-filter-count>${ctx.selected.size} selected. Select at least one value. Filters can remove the saved period; choose another period or clear the filter if that happens.</p><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="story-filter-apply" ${tooMany||!ctx.selected.size?'disabled':''}>Apply to scene</button></div>`);}
function applyStoryFilter(){const ctx=storyFilterContext,sc=storyScene();if(!ctx||ctx.projectId!==project.id||ctx.storyId!==story()?.id||ctx.sceneId!==sc?.id||ctx.chartId!==sc?.chartId||!sc?.state){closeModal();return showToast('The scene changed. Reopen its filter to review it.');}if(!ctx.selected.size||ctx.selected.size>100)return;const c=project.charts.find(c=>c.id===sc.chartId),d=c&&chartDataset(c);if(ctx.stateRef!==sc.state||ctx.rowsRef!==d?.rows||ctx.bindings!==JSON.stringify([c?.x,c?.seriesField,c?.timeEntityField])){closeModal();return showToast('The chart or scene changed. Reopen the filter to review it.');}const state=normalizeSceneState(sc.state);state.filter={role:ctx.role,values:[...ctx.selected]};stopStory();trackChange();sc.state=normalizeSceneState(state);closeModal();settleStoryView();}
function clearStoryFilter(){const sc=storyScene();if(!sc?.state?.filter)return;stopStory();trackChange();sc.state=normalizeSceneState(sc.state);sc.state.filter=null;closeModal();settleStoryView();}
function navigateStoryScene(direction){const layout=storyLayout(story()),current=storyUI.ms,choices=layout.scenes.map(e=>Math.min(e.end,e.start+Math.max(e.overlap,e.scene.transition==='state'?0:e.scene.animationMs)));const index=Math.max(0,layout.scenes.findLastIndex(e=>e.start<=current+1)),next=choices[index+direction];stopStory();if(layout.scenes[index+direction]){storyUI.sceneId=layout.scenes[index+direction].scene.id;storyUI.keyIndex=0;}storyUI.ms=next??(direction>0?layout.duration:0);renderStory();renderStoryInspector();}
function addStoryViewExample(scroll=false){const datasetId=newId('dataset'),chartId=newId('chart'),storyId=newId('story'),ex=(scroll?scrollStoryExample:storyStateExample)({datasetId,chartId,storyId});stopStory();trackChange();project.datasets.push({id:datasetId,name:'Story state example · illustrative data',rows:structuredClone(ex.rows),rawRows:structuredClone(ex.rows),calculations:[],log:[]});project.charts.push(ex.chart);storyList().push(ex.story);storyUI.storyId=storyId;storyUI.sceneId=ex.story.scenes[0].id;storyUI.ms=0;ui.page='story';markDirty();render();showToast('Three saved views of one chart · illustrative data · Undo to remove example');}
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.storyView){changeStoryView(el.dataset.storyView,el.value);return;}if(el.id==='storyFilterRole'&&storyFilterContext){storyFilterContext.role=el.value;storyFilterContext.initial=true;renderStoryFilter();return;}if(el.hasAttribute('data-story-filter-value')&&storyFilterContext){const value=decodeURIComponent(el.dataset.storyFilterValue);if(el.checked)storyFilterContext.selected.add(value);else storyFilterContext.selected.delete(value);const button=document.querySelector('[data-action="story-filter-apply"]');if(button)button.disabled=!storyFilterContext.selected.size;const count=document.querySelector('[data-story-filter-count]');if(count)count.textContent=storyFilterContext.selected.size+' selected. Select at least one value.';}});

function narrativePublication(){return publishUI.kind==='story'&&project.stories?.find(s=>s.id===publishUI.assetId)?.delivery==='scroll';}
function storyChapterControls(st,sc){return `${field('HTML story format',`<select data-story-global="delivery"><option value="player" ${st.delivery!=='scroll'?'selected':''}>Animation player</option><option value="scroll" ${st.delivery==='scroll'?'selected':''}>Scroll story / chapters</option></select>`)}${st.delivery==='scroll'?`${field('Story introduction',`<textarea data-story-global="introduction" maxlength="2000" rows="3">${E(st.introduction||'')}</textarea>`)}${field('Transitions while scrolling',`<select data-story-global="scrollTransitions"><option value="false" ${!st.scrollTransitions?'selected':''}>Switch complete views</option><option value="true" ${st.scrollTransitions?'selected':''}>Use scene transitions</option></select>`)}<div class="story-chapter-edit"><h4>Selected chapter</h4>${field('Chapter title',`<input data-story-scene-setting="chapterTitle" maxlength="120" value="${E(sc.chapterTitle||'')}">`)}${field('Narrative text',`<textarea data-story-scene-setting="chapterText" maxlength="4000" rows="6">${E(sc.chapterText||'')}</textarea>`)}${field('Chart description / reading caption',`<textarea data-story-scene-setting="chapterDescription" maxlength="1000" rows="3">${E(sc.chapterDescription||'')}</textarea>`)}<p class="hint">Text is plain text; blank lines create paragraphs. Describe the chart for readers who cannot see it. Reading view includes every complete chapter chart; it works without JavaScript. Small screens and reduced motion use complete chart states.</p><div class="inline-actions"><button class="secondary-button" data-action="story-preview-scroll">Preview scroll story</button><button class="secondary-button" data-action="story-preview-reading">Preview reading view</button></div></div>`:''}`;}
function previewStoryNarrative(reading=false){const st=story();if(!st?.scenes.length)return showToast('Add a scene first.');stopStory();try{const built=buildStorySources(project,st);if(built.errors.length)throw Error(built.errors[0].message);const html=scrollStoryHtml(st,built.sources,{interactive:!reading});openModal(reading?'Reading view':'Scroll story preview',`<p class="hint">This is the exported ${reading?'reading':'scroll'} HTML. Scroll view uses sticky charts on larger screens; Reading view shows every chart in document order.</p><div class="inline-actions"><button class="secondary-button" data-action="story-preview-scroll">Scroll preview</button><button class="secondary-button" data-action="story-preview-reading">Reading preview</button><button class="secondary-button" data-action="story-reading-download">Download reading HTML</button></div><iframe id="storyNarrativePreview" title="${reading?'Reading view':'Scroll story'} preview" sandbox="allow-scripts" style="width:100%;height:620px;border:1px solid var(--line);border-radius:6px;margin-top:12px;background:white"></iframe>`,true);$('storyNarrativePreview').srcdoc=html;}catch(e){showToast(e.message);}}
function downloadReadingStory(){const st=story();if(!st)return;try{const built=buildStorySources(project,st);if(built.errors.length)throw Error(built.errors[0].message);download('openviz-reading-story.html',new Blob([scrollStoryHtml(st,built.sources,{interactive:false})],{type:'text/html;charset=utf-8'}));showToast('Reading HTML exported');}catch(e){showToast(e.message);}}

function regionalControls(c){if(!['geo-choropleth','geo-symbol'].includes(c.type))return '';return `<div class="regional-boundary-controls"><button class="secondary-button" data-action="map-library-open">Browse map resources & starting points…</button>${isRegional(c)&&c.type==='geo-symbol'?field('Regional calculation',`<select data-setting="aggregation">${selectOptions(['sum','average','count','min','max'],c.aggregation)}</select>`):''}<button class="secondary-button" data-action="regional-open">${c.geoCustom?'Review custom boundaries / joins…':'Import custom region boundaries…'}</button><button class="subtle-button" data-action="regional-example">Try regional map example</button><button class="subtle-button" data-action="map-context-example">Try labels and locator example</button><button class="subtle-button" data-action="map-author-example">Try authored map example</button><button class="subtle-button" data-action="map-projection-example">Try projection example</button>${c.type==='geo-choropleth'?'<button class="subtle-button" data-action="map-class-example">Try classified map example</button><button class="subtle-button" data-action="map-diverging-example">Try diverging map example</button><button class="subtle-button" data-action="map-domain-example">Try custom colour limits example</button><button class="subtle-button" data-action="map-scale-example">Try symmetric-log example</button><button class="subtle-button" data-action="map-log-example">Try logarithmic example</button><button class="subtle-button" data-action="map-legend-example">Try legend layout example</button>':''}${c.geoCustom?`<p class="hint">${E(c.geoCustom.name||'Custom boundaries')} · embedded locally</p><button class="subtle-button" data-action="regional-clear">Use built-in world boundaries</button>`:''}</div>`;}
let regionalContext=null;
function openRegionalManager(){const c=chart(),d=c&&chartDataset(c);if(!['geo-choropleth','geo-symbol'].includes(c?.type)||!d)return;regionalContext={projectId:project.id,chartId:c.id,chartType:c.type,datasetId:d.id,rowsRef:d.rows,originalAsset:c.geoCustom,asset:c.geoCustom,key:c.geoBoundaryKey||'',label:c.geoBoundaryLabel||'',joinMode:c.geoJoinMode==='trim-fold'?'trim-fold':'exact',dataKey:c.x||'',credit:c.geoCustom?.credit||'Provided by you',upload:0,error:''};renderRegionalManager();}
function regionalManagerChart(ctx=regionalContext){const c=project.charts.find(c=>c.id===ctx?.chartId);return c?{...c,geoCustom:ctx.asset,geoBoundaryKey:ctx.key,geoBoundaryLabel:ctx.label,geoJoinMode:ctx.joinMode,x:ctx.dataKey}:null;}
function renderRegionalManager(){const ctx=regionalContext,c=regionalManagerChart(),d=c&&project.datasets.find(d=>d.id===ctx.datasetId);if(!ctx||!c||!d)return;let meta=null,report=null;try{if(ctx.asset){meta=boundaryAsset(ctx.asset);report=regionalReport(d.rows,c);}}catch(e){ctx.error=e.message;}const pick=(id,label,options,value,blank='Choose…')=>field(label,`<select id="${id}"><option value="">${blank}</option>${options.map(v=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(v==='$feature.id'?'Feature ID':v)}</option>`).join('')}</select>`);
 const summary=report&&!report.errors.length?`<div class="regional-review-stats"><div><strong>${report.matchedRegions} / ${report.map.size}</strong><span>Regions with values</span></div><div><strong>${report.unmatchedRows}</strong><span>Unmatched data rows</span></div><div><strong>${report.invalidRows}</strong><span>Invalid measure rows</span></div><div><strong>${report.missingRegions.length}</strong><span>Regions without values</span></div></div>${report.unmatchedKeys.length?`<p class="notice">Unmatched data keys (first 12): ${E(report.unmatchedKeys.join(', '))}</p>`:''}${report.missingRegions.length?`<p class="hint">Regions without values (first 12): ${E(report.missingRegions.slice(0,12).join(', '))}. They remain unshaded; zero is a valid value.</p>`:''}<div class="regional-review-preview">${buildChart(d.rows,{...c,timeEnabled:false,title:'Join review · all source rows',subtitle:'Review combines rows across all periods; chart playback aggregates each period separately.',showSubtitle:true,height:420,sourceNote:'',geoShowBoundaryNote:false},c.type,{width:700,height:420})}</div>`:'';
 openModal('Custom region boundaries',`<div id="regionalManager"><p>Load local GeoJSON, choose a unique boundary property and review its match to your dataset. Nothing changes until you apply this review.</p><label class="field"><span>GeoJSON boundary file</span><input id="regionalBoundaryFile" type="file" accept=".geojson,.json,application/geo+json,application/json"></label><p class="hint">WGS84 longitude/latitude FeatureCollection · Polygon/MultiPolygon · up to 8 MiB, 2,000 features and 150,000 vertices. No remote URLs, projected metre coordinates, shapefiles or TopoJSON.</p>${ctx.error?`<p class="notice" role="alert">${E(ctx.error)}</p>`:''}${meta?`<p class="hint">${E(meta.asset.name)} · ${meta.asset.geojson.features.length} features · ${meta.vertices.toLocaleString()} vertices · ${meta.rings} rings. ${meta.wraps?'Longitude wraps across the antimeridian. ':''}${meta.droppedAltitude?meta.droppedAltitude+' altitude values discarded. ':''}${meta.droppedProperties?meta.droppedProperties+' unsupported properties discarded.':''}</p><div class="regional-review-fields">${pick('regionalBoundaryKey','Unique boundary join property',meta.fields,ctx.key)}${pick('regionalBoundaryLabel','Region label property (optional)',meta.fields,ctx.label,'Use join key')}${pick('regionalDataKey','Data join column',getFields(d.rows),ctx.dataKey)}${field('Match rule',`<select id="regionalJoinMode"><option value="exact" ${ctx.joinMode==='exact'?'selected':''}>Exact displayed text</option><option value="trim-fold" ${ctx.joinMode==='trim-fold'?'selected':''}>Trim + case-insensitive NFC text</option></select>`)}${field('Boundary source / credit',`<input id="regionalCredit" maxlength="500" value="${E(ctx.credit)}">`)}</div>${report?.errors.length?`<p class="notice" role="alert">${E(report.errors.join(' '))}</p>`:summary}<p class="hint">No fuzzy matching or inferred country aliases. Several source records per region use your selected chart calculation (${E(c.aggregation||'sum')}). Data and boundary properties are not rewritten. This review combines all source periods; time playback keeps fixed colour/size scales of per-period aggregates. Regional symbols exclude negative measures; circles use a representative interior point of the largest polygon part, not an observation location. Inspect holes, islands and antimeridian placement. Geometry structure is checked; full topology/overlap validation is not performed.</p>`:''}<div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="regional-apply" ${!meta||report?.errors.length||!ctx.dataKey?'disabled':''}>Use boundaries and join</button></div></div>`,true);}
async function uploadRegionalBoundary(file){const ctx=regionalContext;if(!ctx)return;const upload=++ctx.upload;try{const asset=await importBoundaryFile(file);if(ctx!==regionalContext||upload!==ctx.upload||!$('regionalManager')||project.id!==ctx.projectId)return;ctx.asset=asset;ctx.key='';ctx.label='';ctx.credit=asset.credit;ctx.error='';renderRegionalManager();}catch(e){if(ctx===regionalContext&&upload===ctx.upload&&$('regionalManager')){ctx.error=e.message;renderRegionalManager();}}}
function applyRegionalBoundaries(){const ctx=regionalContext,c=project.charts.find(c=>c.id===ctx?.chartId),d=c&&chartDataset(c);if(!ctx||ctx.projectId!==project.id||!c||!['geo-choropleth','geo-symbol'].includes(c.type)||c.type!==ctx.chartType||chart()?.id!==ctx.chartId||!d||c.datasetId!==ctx.datasetId||d.rows!==ctx.rowsRef||c.geoCustom!==ctx.originalAsset||!$('regionalManager')){closeModal();showToast('The chart or data changed. Reopen the boundary review.');return;}const draft=regionalManagerChart(),report=regionalReport(d.rows,draft);if(report.errors.length||!ctx.asset||!getFields(d.rows).includes(ctx.dataKey))return;const asset=boundaryAsset({...boundaryAsset(ctx.asset).asset,credit:String(ctx.credit).slice(0,500)}).asset;trackChange();Object.assign(c,{geoCustom:asset,geoBoundaryKey:ctx.key,geoBoundaryLabel:ctx.label,geoJoinMode:ctx.joinMode,x:ctx.dataKey});closeModal();markDirty();render();showToast('Custom boundaries and reviewed join applied · Undo to restore');}
function clearRegionalBoundaries(){const c=chart();if(!c?.geoCustom)return;trackChange();Object.assign(c,{geoCustom:null,geoBoundaryKey:'',geoBoundaryLabel:'',geoJoinMode:'exact'});markDirty();render();showToast('World boundaries restored · choose a country/ISO data field if needed');}
function addRegionalExample(context=false){const ex=['scale','log','legend','tooltip','tooltip-fields','explore','navigate'].includes(context)?regionalScaleExample(['log','tooltip','tooltip-fields','explore','navigate'].includes(context)?'log':'symlog'):['classification','diverging','domain'].includes(context)?regionalClassifiedExample():regionalExample(),symbol=chart()?.type==='geo-symbol',datasetId=newId('dataset'),id=newId('chart');if(['tooltip-fields','explore','navigate'].includes(context))ex.rows=ex.rows.map((r,i)=>({...r,Context:r.Region==='A'&&r.Year===2020?(i===0?'First observation':'Second observation'):'Illustrative context '+r.Region,Secondary:i%4===0?null:(i+1)*2.25}));trackChange();project.datasets.push({id:datasetId,name:'Illustrative district data',rows:structuredClone(ex.rows),rawRows:structuredClone(ex.rows),calculations:[],source:'OpenViz illustrative example',log:[]});project.charts.push({...structuredClone(DEFAULT_CHART),...ex.settings,...(context?{geoShowLabels:true,geoShowLocator:true}:{}),...(context==='authored'?regionalAuthoredSettings(symbol):{}),...(['explore','navigate'].includes(context)?{geoExploreEnabled:true,...(context==='navigate'?{geoNavigationEnabled:true}:{})}:{}),...(['tooltip-fields','explore','navigate'].includes(context)?{geoTooltipFields:[{...newTooltipField(),field:'Context',label:'Context',aggregation:'unique'},{...newTooltipField(),field:'Secondary',label:'Secondary measure',aggregation:'average',format:'decimal'}]}:{}),...(['tooltip','tooltip-fields','explore','navigate'].includes(context)?{geoTooltipMode:'custom',geoTooltipNameLabel:'District',geoTooltipValueLabel:'Amount',geoTooltipNumberFormat:'decimal',geoTooltipDecimals:1,geoTooltipSuffix:' units'}:{}),...(context==='legend'?{geoLegendLayout:'list',geoLegendAlign:'right',geoLegendWidth:60,geoLegendFontSize:11,geoLegendNumberFormat:'compact',geoLegendDecimals:1,geoLegendSuffix:' kg',geoClassification:'equal',geoClassCount:5,geoLegendTitle:'Illustrative change (kg)'}:{}),...(context==='scale'?{geoScaleType:'symlog',geoSymlogConstant:10,geoColorMode:'diverging',geoMidpoint:0,geoDivergingRange:'symmetric',geoLegendTitle:'Signed values · symmetric log'}:{}),...(context==='domain'?{geoDomainMode:'custom',geoDomainMin:-20,geoDomainMax:60,geoColorMode:'diverging',geoMidpoint:0,geoClassification:'continuous',geoLegendTitle:'Shared colour scale · −20 to 60'}:{}),...(context==='diverging'?{geoColorMode:'diverging',geoClassification:'continuous',geoMidpoint:0,geoDivergingRange:'symmetric',geoLegendTitle:'Change around zero',geoNoDataColor:'#b7c6d2'}:{}),...(context==='classification'?{geoClassification:'quantile',geoClassCount:4,geoLegendTitle:'Illustrative regional values',geoNoDataColor:'#b7c6d2'}:{}),...(context==='projection'?{...regionalAuthoredSettings(symbol),geoProjection:'equalArea',geoFramePadding:8}:{}),...(symbol?{type:'geo-symbol',title:'Illustrative regional symbols'}:{}),id,datasetId});ui.selectedChartId=id;ui.selectedDatasetId=datasetId;ui.chartSelection=null;ui.studioTab='preview';ui.page='visualise';markDirty();render();showToast('Illustrative regions added · these are not real administrative boundaries');}
document.addEventListener('change',event=>{const el=event.target;if(el.id==='regionalBoundaryFile'){uploadRegionalBoundary(el.files?.[0]);return;}const ctx=regionalContext;if(!ctx||!$('regionalManager'))return;const setting={regionalBoundaryKey:'key',regionalBoundaryLabel:'label',regionalDataKey:'dataKey',regionalJoinMode:'joinMode',regionalCredit:'credit'}[el.id];if(setting){ctx[setting]=el.value;renderRegionalManager();}});

let mapAuthor=null;
function openMapAuthor(){const c=chart(),d=c&&chartDataset(c);if(!c||!d||!GEO_TYPES.has(c.type))return;try{const targets=c.type==='geo-heat'?[]:mapEditableTargets(d.rows,c);mapAuthor={projectId:project.id,chartId:c.id,type:c.type,datasetId:d.id,rows:d.rows,asset:c.geoCustom,original:JSON.stringify(validateMapAuthoring(c)),draft:validateMapAuthoring(c),editIndex:null,targets,target:targets[0]?.id||'',error:''};renderMapAuthor();}catch(e){showToast(e.message);}}
function renderMapAuthor(){const ctx=mapAuthor,c=project.charts.find(c=>c.id===ctx?.chartId);if(!ctx||!c)return;const note=Number.isInteger(ctx.editIndex)?ctx.draft.geoAnnotations[ctx.editIndex]:null,target=ctx.targets.find(t=>t.id===ctx.target),pos=Object.hasOwn(ctx.draft.geoLabelPositions,ctx.target)?ctx.draft.geoLabelPositions[ctx.target]:null,anchor=Object.hasOwn(ctx.draft.geoSymbolAnchors,ctx.target)?ctx.draft.geoSymbolAnchors[ctx.target]:null,numeric=(id,label,value,min,max)=>field(label,`<input id="${id}" type="number" step="any" min="${min}" max="${max}" value="${E(value)}">`),preview=buildChart(ctx.rows,{...c,...ctx.draft,geoShowLabels:c.geoShowLabels||Object.keys(ctx.draft.geoLabelPositions).length>0},c.type,{width:700,height:460});
 openModal('Map positions & annotations',`<div id="mapAuthor"><p>Preview display edits before applying. Label centres use percentages of the map plot, so they adapt to canvas size. Manual labels take priority and may overlap; inspect narrow exports. Symbol anchors and callout points use WGS84 longitude/latitude.</p>${ctx.error?`<p class="notice" role="alert">${E(ctx.error)}</p>`:''}${target?`<h4>Label / region</h4>${field('Place or region',`<select id="mapAuthorTarget">${ctx.targets.map(t=>`<option value="${E(t.id)}" ${t.id===ctx.target?'selected':''}>${E(t.name)} · ${E(t.id)}</option>`).join('')}</select>`)}<div class="map-author-fields">${numeric('mapLabelX','Label centre X (%)',pos?pos.x*100:50,0,100)}${numeric('mapLabelY','Label centre Y (%)',pos?pos.y*100:50,0,100)}<label><input id="mapLabelHidden" type="checkbox" ${pos?.hidden?'checked':''}> Hide this name</label></div><div class="inline-actions"><button class="secondary-button" data-action="map-author-label">Set label position / visibility</button><button class="subtle-button" data-action="map-author-label-reset">Reset this label to automatic</button></div>${isRegional(c)&&c.type==='geo-symbol'?`<h4>Custom region symbol anchor</h4><p class="hint">A display position, not an observation location. Anchors outside the imported extent fall back to automatic. Label leaders follow the symbol.</p><div class="map-author-fields">${numeric('mapAnchorLon','Symbol longitude',anchor?.lon??target.anchor?.[0]??0,-180,180)}${numeric('mapAnchorLat','Symbol latitude',anchor?.lat??target.anchor?.[1]??0,-90,90)}</div><div class="inline-actions"><button class="secondary-button" data-action="map-author-anchor">Set symbol anchor</button><button class="subtle-button" data-action="map-author-anchor-reset">Reset this anchor</button></div>`:''}`:'<p class="hint">No eligible labels. Annotations remain available.</p>'}<h4>Map annotations (${ctx.draft.geoAnnotations.length}/20)</h4><p class="hint">Callouts are plain text. Points outside the displayed extent are not drawn. They apply to every time period, including periods without data. Stage each edit with its Set / Add button before choosing Apply.</p>${field('Callout text',`<input id="mapNoteText" maxlength="240" value="${E(note?.text||'')}" placeholder="Explain a place or feature…">`)}<div class="map-author-fields">${numeric('mapNoteLon','Point longitude',note?.lon??target?.anchor?.[0]??0,-180,180)}${numeric('mapNoteLat','Point latitude',note?.lat??target?.anchor?.[1]??0,-90,90)}${numeric('mapNoteX','Callout centre X (%)',note?note.x*100:70,0,100)}${numeric('mapNoteY','Callout centre Y (%)',note?note.y*100:15,0,100)}</div><button class="secondary-button" data-action="map-author-note">${note?'Save callout':'Add callout'}</button><button class="subtle-button" data-action="map-author-note-new">New callout</button><ol>${ctx.draft.geoAnnotations.map((n,i)=>`<li>${E(n.text)} <button class="subtle-button" data-action="map-author-note-edit" data-index="${i}">Edit</button><button class="subtle-button" data-action="map-author-note-remove" data-index="${i}">Remove</button></li>`).join('')}</ol><div class="regional-review-preview">${preview}</div><p class="hint">Preview uses the saved period. Reset removes staged positions/callouts; source rows and geometry remain intact. Manual callouts can cover labels, symbols or the locator. Long callouts are shortened visually; their full text remains in the title and accessible description.</p><div class="modal-actions"><button class="subtle-button" data-action="map-author-reset-all">Reset all map authoring</button><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="map-author-apply">Apply map edits</button></div></div>`,true);
}
const mapAuthorNumber=id=>{const el=$(id);return el?.value.trim()===''?NaN:Number(el?.value);};
function checkMapDraft(change){if(!mapAuthor||!$('mapAuthor'))return;try{const next=structuredClone(mapAuthor.draft);change(next);mapAuthor.draft=validateMapAuthoring(next);mapAuthor.error='';}catch(e){mapAuthor.error=e.message;}renderMapAuthor();}
function stageMapLabel(){checkMapDraft(next=>{Object.defineProperty(next.geoLabelPositions,mapAuthor.target,{value:{x:mapAuthorNumber('mapLabelX')/100,y:mapAuthorNumber('mapLabelY')/100,hidden:!!$('mapLabelHidden')?.checked},enumerable:true,writable:true,configurable:true});});}
function stageMapReset(key){checkMapDraft(next=>{delete next[key][mapAuthor.target];});}
function stageMapAnchor(){checkMapDraft(next=>{Object.defineProperty(next.geoSymbolAnchors,mapAuthor.target,{value:{lon:mapAuthorNumber('mapAnchorLon'),lat:mapAuthorNumber('mapAnchorLat')},enumerable:true,writable:true,configurable:true});});}
function stageMapNote(){checkMapDraft(next=>{const note={text:$('mapNoteText')?.value.trim()||'',lon:mapAuthorNumber('mapNoteLon'),lat:mapAuthorNumber('mapNoteLat'),x:mapAuthorNumber('mapNoteX')/100,y:mapAuthorNumber('mapNoteY')/100};if(Number.isInteger(mapAuthor.editIndex))next.geoAnnotations[mapAuthor.editIndex]=note;else next.geoAnnotations.push(note);});}
function applyMapAuthor(){const ctx=mapAuthor,c=chart(),d=c&&chartDataset(c);if(!ctx||!$('mapAuthor')||project.id!==ctx.projectId||c?.id!==ctx.chartId||c.type!==ctx.type||d?.id!==ctx.datasetId||d.rows!==ctx.rows||c.geoCustom!==ctx.asset||JSON.stringify(validateMapAuthoring(c))!==ctx.original){closeModal();showToast('The map or data changed. Reopen map authoring.');return;}try{const edits=validateMapAuthoring(ctx.draft);trackChange();Object.assign(c,edits);if(Object.keys(edits.geoLabelPositions).length)c.geoShowLabels=true;closeModal();markDirty();render();showToast('Map display edits applied · Undo to restore');}catch(e){ctx.error=e.message;renderMapAuthor();}}
document.addEventListener('change',event=>{if(event.target.id==='mapAuthorTarget'&&mapAuthor&&$('mapAuthor')){mapAuthor.target=event.target.value;mapAuthor.error='';renderMapAuthor();}});

let mapFrame=null;
function openMapFrame(){const c=chart(),d=c&&chartDataset(c);if(!c||!d||!GEO_TYPES.has(c.type))return;try{mapFrame={projectId:project.id,id:c.id,type:c.type,datasetId:d.id,rows:d.rows,asset:c.geoCustom,original:JSON.stringify([c.geoProjection,c.geoFramePadding,c.geoExtent]),automatic:currentMapExtent(d.rows,{...c,geoExtent:null}),draft:c.geoExtent?[...c.geoExtent]:null,error:''};renderMapFrame();}catch(e){showToast(e.message);}}
function renderMapFrame(){const ctx=mapFrame,c=project.charts.find(c=>c.id===ctx?.id);if(!ctx||!c)return;const v=ctx.draft||ctx.automatic,fields=['West longitude','South latitude','East longitude','North latitude'];openModal('Geographic map extent',`<div id="mapFrame"><p>Set a geographic crop without editing source data or boundary geometry. East may be less than west to cross the antimeridian; equal west/east is invalid. Use −180 to 180 for the full longitude span.</p>${ctx.error?`<p class="notice" role="alert">${E(ctx.error)}</p>`:''}<label><input id="mapFrameCustom" type="checkbox" ${ctx.draft?'checked':''}> Use custom extent</label><div class="map-author-fields">${fields.map((label,i)=>field(label,`<input id="mapFrame${i}" type="number" step="any" value="${E(v[i])}">`)).join('')}</div><div class="inline-actions"><button class="secondary-button" data-action="map-frame-preview">Preview extent</button><button class="subtle-button" data-action="map-frame-auto">Restore automatic framing</button></div><div class="regional-review-preview">${buildChart(ctx.rows,{...c,geoExtent:ctx.draft},c.type,{width:700,height:460})}</div><p class="hint">Preview uses the saved period and selected projection. Coordinates/labels outside the extent are omitted; intersecting polygons are clipped. Mercator's displayed latitude range is limited to ±85.0511°. Frame padding adds space without changing the geographic extent or locator focus. The same extent is retained across time snapshots.</p><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="map-frame-apply">Apply extent</button></div></div>`,true);}
function readMapFrame(){const c=chart();const extent=$('mapFrameCustom')?.checked?[0,1,2,3].map(i=>{const v=$('mapFrame'+i)?.value;return v?.trim()===''?NaN:Number(v);}):null;validateMapFrame({...c,geoExtent:extent});return extent;}
function previewMapFrame(){if(!mapFrame||!$('mapFrame'))return;try{mapFrame.draft=readMapFrame();mapFrame.error='';}catch(e){mapFrame.error=e.message;}renderMapFrame();}
function applyMapFrame(){const ctx=mapFrame,c=chart(),d=c&&chartDataset(c);if(!ctx||!$('mapFrame')||ctx.projectId!==project.id||c?.id!==ctx.id||c.type!==ctx.type||d?.id!==ctx.datasetId||d.rows!==ctx.rows||c.geoCustom!==ctx.asset||JSON.stringify([c.geoProjection,c.geoFramePadding,c.geoExtent])!==ctx.original){closeModal();showToast('The map changed. Reopen geographic framing.');return;}try{const extent=readMapFrame();trackChange();c.geoExtent=extent;closeModal();markDirty();render();showToast('Map framing applied · Undo to restore');}catch(e){ctx.error=e.message;renderMapFrame();}}

const mapClassKeys=['geoLegendAlign','geoLegendLayout','geoLegendWidth','geoLegendFontSize','geoLegendNumberFormat','geoLegendDecimals','geoLegendPrefix','geoLegendSuffix','geoScaleType','geoSymlogConstant','geoDomainMode','geoDomainMin','geoDomainMax','geoClassification','geoClassCount','geoClassBreaks','geoLegendTitle','geoLegendNoData','geoNoDataLabel','geoNoDataColor','geoColorMode','geoMidpoint','geoDivergingRange','geoLowColor','geoMidColor','geoHighColor'];
let mapClass=null;
function classSettings(c){return Object.fromEntries(mapClassKeys.map(k=>[k,structuredClone(c[k]??DEFAULT_CHART[k])]));}
function openMapClass(){const c=chart(),d=c&&chartDataset(c);if(c?.type!=='geo-choropleth'||!d)return;mapClass={projectId:project.id,id:c.id,datasetId:d.id,rows:d.rows,asset:c.geoCustom,original:JSON.stringify(classSettings(c)),draft:classSettings(c),error:'',rawBreaks:(c.geoClassBreaks||[]).join(', ')};renderMapClass();}
function renderMapClass(){const ctx=mapClass,c=project.charts.find(c=>c.id===ctx?.id);if(!ctx||!c)return;const cfg={...c,...ctx.draft};openModal('Choropleth classification & legend',`<div id="mapClass"><p>Choose how numeric region aggregates map to colour. This review does not alter source rows or calculations. Time maps keep one set of breaks across every period, based on per-period aggregates, not combined multi-year totals.</p>${ctx.error?`<p class="notice" role="alert">${E(ctx.error)}</p>`:''}<div class="map-author-fields">${field('Classification',`<select id="mapClassMethod">${Object.entries(MAP_CLASSES).map(([id,label])=>`<option value="${id}" ${ctx.draft.geoClassification===id?'selected':''}>${E(label)}</option>`).join('')}</select>`)}${field('Requested classes (automatic methods)',`<input id="mapClassCount" ${['manual','continuous'].includes(ctx.draft.geoClassification)?'disabled':''} type="number" min="2" max="7" step="1" value="${ctx.draft.geoClassCount}">`)}</div>${field('Manual breaks (1–6 thresholds; used only for Manual)',`<input id="mapClassBreaks" ${ctx.draft.geoClassification!=='manual'?'disabled':''} value="${E(ctx.rawBreaks)}" placeholder="e.g. -10, 0, 10, 25">`)}<p class="hint">Intervals are lower-inclusive, upper-exclusive: &lt; first break, then a ≤ value &lt; b, then ≥ last break. Negative values and genuine zero remain values. Quantiles use linearly interpolated percentiles of matched region aggregates; ties may reduce classes and do not guarantee equal counts. Manual outer classes are unbounded.</p><h4>Colour scale</h4><div class="map-author-fields">${field('Scale transformation',`<select id="mapScaleType" ${!['continuous','equal'].includes(ctx.draft.geoClassification)?'disabled':''}><option value="linear" ${ctx.draft.geoScaleType==='linear'?'selected':''}>Linear</option><option value="log" ${ctx.draft.geoScaleType==='log'?'selected':''}>Logarithmic (positive values)</option><option value="symlog" ${ctx.draft.geoScaleType==='symlog'?'selected':''}>Symmetric log (signed values)</option></select>`)}${field('Symmetric-log constant (value units)',`<input id="mapSymlogConstant" type="number" step="any" min="0" ${ctx.draft.geoScaleType!=='symlog'?'disabled':''} value="${E(ctx.draft.geoSymlogConstant)}">`)}</div><p class="hint">Logarithmic requires every matched aggregate and both scale limits to be positive. Zero and negatives are rejected, not hidden. Symmetric log accepts signed values and zero; its positive constant controls the near-zero region in the original value units. Both support Continuous and Equal interval. Equal interval then means equal spacing in transformed space; legend thresholds stay in original units. Quantile and Manual restore Linear. Source data and tooltips keep their original values.</p><div class="map-author-fields">${field('Colour mode',`<select id="mapColorMode"><option value="sequential" ${ctx.draft.geoColorMode==='sequential'?'selected':''}>Sequential palette</option><option value="diverging" ${ctx.draft.geoColorMode==='diverging'?'selected':''}>Diverging around midpoint</option></select>`)}${field('Reference midpoint',`<input id="mapMidpoint" type="number" step="any" ${ctx.draft.geoColorMode!=='diverging'?'disabled':''} value="${ctx.draft.geoMidpoint}">`)}${field('Diverging range',`<select id="mapDivergingRange" ${ctx.draft.geoColorMode!=='diverging'||ctx.draft.geoDomainMode==='custom'?'disabled':''}><option value="independent" ${ctx.draft.geoDivergingRange==='independent'?'selected':''}>Independent sides</option><option value="symmetric" ${ctx.draft.geoDivergingRange==='symmetric'?'selected':''}>Symmetric distance</option></select>`)}${field('Preset (sets the three colour controls)',`<select id="mapDivergingPreset" ${ctx.draft.geoColorMode!=='diverging'?'disabled':''}><option value="">Choose / custom colours…</option><option value="orangeBlue">Orange / neutral / blue</option><option value="purpleGreen">Purple / neutral / green</option><option value="redBlue">Red / neutral / blue</option></select>`)}</div><div class="map-author-fields">${[['mapLowColor','Below midpoint colour','geoLowColor'],['mapMidColor','Midpoint / neutral colour','geoMidColor'],['mapHighColor','Above midpoint colour','geoHighColor']].map(([id,label,key])=>field(label,`<input id="${id}" type="color" ${ctx.draft.geoColorMode!=='diverging'?'disabled':''} value="${E(ctx.draft[key])}">`)).join('')}</div><p class="hint">Continuous diverging colour equals the neutral stop at the exact midpoint. Independent sides each use their observed extreme; symmetric distance uses equal numeric ranges around the midpoint and can extend beyond observed values. Classified colours represent whole intervals: the class containing an observed midpoint is neutral, not just the midpoint value. To distinguish individual values either side of a reference, use Continuous or suitable manual breaks. No-data remains separate.</p><h4>Comparable map scales</h4><div class="map-author-fields">${field('Colour limits',`<select id="mapDomainMode" ${!['continuous','equal'].includes(ctx.draft.geoClassification)?'disabled':''}><option value="auto" ${ctx.draft.geoDomainMode!=='custom'?'selected':''}>Automatic from matched values</option><option value="custom" ${ctx.draft.geoDomainMode==='custom'?'selected':''}>Custom numeric limits</option></select>`)}${[['mapDomainMin','Colour minimum','geoDomainMin'],['mapDomainMax','Colour maximum','geoDomainMax']].map(([id,label,key])=>field(label,`<input id="${id}" type="number" step="any" ${ctx.draft.geoDomainMode!=='custom'?'disabled':''} value="${E(ctx.draft[key]??'')}">`)).join('')}</div><p class="hint">Use matching units and aggregation, plus the same limits, palette/colour stops, midpoint, transformation/constant and method on each map to compare colours. Custom limits support Continuous and Equal interval; quantiles follow each dataset and manual breaks define their own shared thresholds. Values outside the limits retain their actual values and use endpoint colours or outer classes. The legend reports their counts across all periods. Custom endpoints override automatic symmetric/independent fitting; choose endpoints equally spaced from the midpoint for a symmetric custom range. Restore Automatic to fit the data again.</p><h4>Legend layout & numbers</h4><div class="map-author-fields">${field('Class key layout',`<select id="mapLegendLayout" ${ctx.draft.geoClassification==='continuous'?'disabled':''}><option value="auto" ${ctx.draft.geoLegendLayout==='auto'?'selected':''}>Automatic grid</option><option value="list" ${ctx.draft.geoLegendLayout==='list'?'selected':''}>Vertical list</option></select>`)}${field('Block alignment',`<select id="mapLegendAlign">${[['left','Left'],['center','Centre'],['right','Right']].map(([id,label])=>`<option value="${id}" ${ctx.draft.geoLegendAlign===id?'selected':''}>${label}</option>`).join('')}</select>`)}${field('Block width (% of map plot)',`<input id="mapLegendWidth" type="number" min="25" max="100" step="1" value="${E(ctx.draft.geoLegendWidth)}">`)}${field('Legend text size',`<input id="mapLegendFontSize" type="number" min="9" max="16" step="1" value="${E(ctx.draft.geoLegendFontSize)}">`)}${field('Number format',`<select id="mapLegendFormat">${[['auto','Automatic'],['decimal','Decimal'],['compact','Compact (k, M, B, T)'],['scientific','Scientific']].map(([id,label])=>`<option value="${id}" ${ctx.draft.geoLegendNumberFormat===id?'selected':''}>${label}</option>`).join('')}</select>`)}${field('Decimal places (explicit formats)',`<input id="mapLegendDecimals" type="number" min="0" max="6" step="1" ${ctx.draft.geoLegendNumberFormat==='auto'?'disabled':''} value="${E(ctx.draft.geoLegendDecimals)}">`)}${field('Prefix (e.g. $)',`<input id="mapLegendPrefix" maxlength="16" value="${E(ctx.draft.geoLegendPrefix)}">`)}${field('Suffix / unit (e.g. %, or a space then kg)',`<input id="mapLegendSuffix" maxlength="16" value="${E(ctx.draft.geoLegendSuffix)}">`)}</div><p class="hint">Alignment positions a narrower legend block below the map; reduce its width to see the effect. Blocks retain a 120px minimum where space allows. Larger type and vertical lists reserve more space and can grow a short canvas. Prefix/suffix are literal labels: % does not multiply values or convert units. Rounded labels use ≈; exact thresholds stay in titles. These controls affect this choropleth legend, not data, map tooltips, source notes or symbol-size legends.</p>${field('Legend title (blank uses value field + method)',`<input id="mapClassTitle" maxlength="80" value="${E(ctx.draft.geoLegendTitle)}">`)}<div class="map-author-fields">${field('No-data label',`<input id="mapClassMissingLabel" maxlength="40" value="${E(ctx.draft.geoNoDataLabel)}">`)}${field('No-data colour',`<input id="mapClassMissingColor" type="color" value="${E(ctx.draft.geoNoDataColor)}">`)}</div><label><input id="mapClassMissingKey" type="checkbox" ${ctx.draft.geoLegendNoData?'checked':''}> Include no-data key in legend</label><p class="hint">No-data colouring applies to absent/invalid regions, not zero. Manual point colours can override class colours and are disclosed in the legend. Cropping does not recalculate the breaks. Legends reserve space below the map; very short canvases grow to fit.</p><button class="secondary-button" data-action="map-class-preview">Preview classification</button><div class="regional-review-preview">${ctx.error?'':buildChart(ctx.rows,cfg,c.type,{width:700,height:500})}</div><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary" data-action="map-class-apply">Apply classification & legend</button></div></div>`,true);}
function readMapClass(){const active=$('mapColorMode').value==='diverging',original=JSON.parse(mapClass.original);const text=$('mapClassBreaks')?.value||'',breaks=text.trim()?text.trim().split(/[\s,]+/).map(Number):[],next={geoLegendAlign:$('mapLegendAlign').value,geoLegendLayout:$('mapLegendLayout').value,geoLegendWidth:$('mapLegendWidth').value.trim()===''?NaN:Number($('mapLegendWidth').value),geoLegendFontSize:$('mapLegendFontSize').value.trim()===''?NaN:Number($('mapLegendFontSize').value),geoLegendNumberFormat:$('mapLegendFormat').value,geoLegendDecimals:$('mapLegendFormat').value==='auto'?original.geoLegendDecimals:($('mapLegendDecimals').value.trim()===''?NaN:Number($('mapLegendDecimals').value)),geoLegendPrefix:$('mapLegendPrefix').value,geoLegendSuffix:$('mapLegendSuffix').value,geoScaleType:['continuous','equal'].includes($('mapClassMethod').value)?$('mapScaleType').value:'linear',geoSymlogConstant:$('mapScaleType').value==='symlog'&&!$('mapScaleType').disabled?($('mapSymlogConstant').value.trim()===''?NaN:Number($('mapSymlogConstant').value)):original.geoSymlogConstant,geoDomainMode:['continuous','equal'].includes($('mapClassMethod').value)?$('mapDomainMode').value:'auto',geoDomainMin:$('mapDomainMode').value==='custom'&&!$('mapDomainMode').disabled?($('mapDomainMin').value.trim()===''?NaN:Number($('mapDomainMin').value)):original.geoDomainMin,geoDomainMax:$('mapDomainMode').value==='custom'&&!$('mapDomainMode').disabled?($('mapDomainMax').value.trim()===''?NaN:Number($('mapDomainMax').value)):original.geoDomainMax,geoClassification:$('mapClassMethod').value,geoClassCount:Number($('mapClassCount').value),geoClassBreaks:$('mapClassMethod').value==='manual'?breaks:JSON.parse(mapClass.original).geoClassBreaks,geoLegendTitle:$('mapClassTitle').value,geoLegendNoData:!!$('mapClassMissingKey').checked,geoNoDataLabel:$('mapClassMissingLabel').value,geoNoDataColor:$('mapClassMissingColor').value,geoColorMode:$('mapColorMode').value,geoMidpoint:active?($('mapMidpoint').value.trim()===''?NaN:Number($('mapMidpoint').value)):original.geoMidpoint,geoDivergingRange:active?$('mapDivergingRange').value:original.geoDivergingRange,geoLowColor:active?$('mapLowColor').value:original.geoLowColor,geoMidColor:active?$('mapMidColor').value:original.geoMidColor,geoHighColor:active?$('mapHighColor').value:original.geoHighColor};mapClass.rawBreaks=text;mapClass.draft=next;validateMapClassification(next);return next;}
function previewMapClass(){if(!mapClass||!$('mapClass'))return;try{const settings=readMapClass();validateMapClassRows(mapClass,settings);mapClass.error='';}catch(e){mapClass.error=e.message;}renderMapClass();}
function applyMapClass(){const ctx=mapClass,c=chart(),d=c&&chartDataset(c);if(!ctx||!$('mapClass')||project.id!==ctx.projectId||c?.id!==ctx.id||c.type!=='geo-choropleth'||d?.id!==ctx.datasetId||d.rows!==ctx.rows||c.geoCustom!==ctx.asset||JSON.stringify(classSettings(c))!==ctx.original){closeModal();showToast('The map changed. Reopen classification review.');return;}try{const settings=readMapClass();validateMapClassRows(ctx,settings);trackChange();Object.assign(c,settings);closeModal();markDirty();render();showToast('Map classification applied · Undo to restore');}catch(e){ctx.error=e.message;renderMapClass();}}

function syncMapClassControls(){if(!$('mapClass'))return;const method=$('mapClassMethod').value,supported=['continuous','equal'].includes(method),active=$('mapColorMode').value==='diverging';$('mapLegendLayout').disabled=method==='continuous';$('mapLegendDecimals').disabled=$('mapLegendFormat').value==='auto';$('mapClassBreaks').disabled=method!=='manual';$('mapClassCount').disabled=method==='manual'||method==='continuous';$('mapScaleType').disabled=!supported;if(!supported)$('mapScaleType').value='linear';$('mapSymlogConstant').disabled=!supported||$('mapScaleType').value!=='symlog';$('mapDomainMode').disabled=!supported;if(!supported)$('mapDomainMode').value='auto';const custom=supported&&$('mapDomainMode').value==='custom';for(const id of ['mapDomainMin','mapDomainMax'])$(id).disabled=!custom;for(const id of ['mapMidpoint','mapDivergingPreset','mapLowColor','mapMidColor','mapHighColor'])$(id).disabled=!active;$('mapDivergingRange').disabled=!active||custom;}
document.addEventListener('change',event=>{if(!$('mapClass'))return;if(['mapClassMethod','mapColorMode','mapDomainMode','mapScaleType','mapLegendFormat'].includes(event.target.id))syncMapClassControls();if(event.target.id==='mapDivergingPreset'){const presets={orangeBlue:['#b35806','#f7f7f7','#2166ac'],purpleGreen:['#762a83','#f7f7f7','#1b7837'],redBlue:['#b2182b','#f7f7f7','#2166ac']},colours=presets[event.target.value];if(colours)for(const [i,id] of ['mapLowColor','mapMidColor','mapHighColor'].entries())$(id).value=colours[i];}});

function validateMapClassRows(ctx,settings){const c=project.charts.find(c=>c.id===ctx.id),cfg={...c,...settings};let result;if(cfg.timeEnabled){const model=timeModel(ctx.rows,cfg);if(model.errors.length)throw Error(model.errors[0]);result=geoTimeDomain(model.frames,cfg);}else result=geoStaticClassification(ctx.rows,cfg);if(result.error)throw Error(result.error);}

