function saveMapCanvasPosition(edit,ctx){if(!mapCanvasCurrent(ctx))return false;try{const c=chart(),next=validateMapAuthoring(c);if(JSON.stringify(next)!==ctx.original)return false;if(edit.kind==='label'){Object.defineProperty(next.geoLabelPositions,edit.id,{value:{x:edit.x,y:edit.y,hidden:false},enumerable:true,writable:true,configurable:true});}else{const index=Number(edit.id);if(!Number.isInteger(index)||!next.geoAnnotations[index])return false;next.geoAnnotations[index]={...next.geoAnnotations[index],x:edit.x,y:edit.y};}validateMapAuthoring({...c,...next});const slider=$('liveChartSvg')?.querySelector('[data-time-slider]'),period=slider?Number(slider.value):null;trackChange();Object.assign(c,next);if(edit.kind==='label')c.geoShowLabels=true;markDirty();renderToolbar();renderChartPreview();renderInspector();const fresh=$('liveChartSvg')?.querySelector('[data-time-slider]');if(fresh&&period!==null){fresh.value=String(period);fresh.dispatchEvent(new window.Event('input',{bubbles:true}));}return true;}catch(e){showToast(e.message);return false;}}
function syncMapCanvasRuntime(){const root=$('liveChartSvg');if(!root)return;if(mapCanvasRuntime?.root!==root){mapCanvasRuntime?.disconnect();const runtime=installMapCanvasEditing(root,{getContext:mapCanvasContext,isCurrent:mapCanvasCurrent,commit:saveMapCanvasPosition,pause:()=>{for(const player of installEditorRace.players||[])player.pause();enableChartHover.runtime?.hide();},status:message=>{const hint=$('selectedElementHint');if(hint)hint.textContent=message;},open:target=>{if(!mapCanvasContext())return;for(const player of installEditorRace.players||[])player.pause();openMapAuthor();if(!mapAuthor)return;if(target.kind==='label'){mapAuthor.target=target.id;mapAuthor.editIndex=null;}else mapAuthor.editIndex=Number(target.id);renderMapAuthor();$(target.kind==='label'?'mapLabelX':'mapNoteText')?.focus();}});mapCanvasRuntime={root,...runtime};}mapCanvasRuntime.setEnabled(!!ui.mapCanvasEdit&&ui.page==='visualise'&&ui.studioTab==='preview'&&GEO_TYPES.has(chart()?.type)&&chart()?.type!=='geo-route');}

