function syncMapTooltipControls(){syncTooltipFieldControls();if(!$('mapTooltip'))return;const active=$('mapTipMode').value==='custom',value=$('mapTipShowValue').checked;for(const el of $('mapTooltip').querySelectorAll('[data-map-tip-key]'))if(el.id!=='mapTipMode')el.disabled=!active;for(const key of ['ValueLabel','NumberFormat','Prefix','Suffix'])$('mapTip'+key).disabled=!active||!value;$('mapTipShowExact').disabled=!active||(!value&&!mapTooltip.draft.geoTooltipFields.length);$('mapTipDecimals').disabled=!active||!value||$('mapTipNumberFormat').value==='auto';$('mapTipShowCoordinates').disabled=!active||!['geo-symbol','geo-route'].includes(mapTooltip.type);$('mapTipShowPeriod').disabled=!active||!chart()?.timeEnabled;}
function readMapTooltip(validate=true){const original=JSON.parse(mapTooltip.original),active=$('mapTipMode').value==='custom',draft={...original,geoTooltipMode:$('mapTipMode').value};if(active)for(const key of MAP_TOOLTIP_KEYS){if(['geoTooltipMode','geoTooltipFields'].includes(key))continue;const el=$(mapTipId(key));if(el.disabled)continue;draft[key]=el.type==='checkbox'?el.checked:key==='geoTooltipDecimals'?(el.value.trim()===''?NaN:Number(el.value)):el.value;}if(active)draft.geoTooltipFields=readTooltipFields();mapTooltip.draft=draft;if(validate){validateMapTooltip(draft);for(const f of draft.geoTooltipFields)if(!getFields(mapTooltip.rows).includes(f.field))throw Error('Tooltip source column is missing: '+f.field);}return draft;}
