function applyMapTooltip(){const ctx=mapTooltip,c=chart(),d=c&&chartDataset(c);if(!ctx||!$('mapTooltip')||ctx.projectId!==project.id||c?.id!==ctx.id||c.type!==ctx.type||d?.id!==ctx.datasetId||d.rows!==ctx.rows||c.geoCustom!==ctx.asset||mapTooltipBindings(c)!==ctx.bindings||JSON.stringify(mapTooltipSettings(c))!==ctx.original){closeModal();showToast('The map or data changed. Reopen tooltips to review them.');return;}try{const settings=readMapTooltip();trackChange();Object.assign(c,settings);closeModal();markDirty();render();showToast('Map tooltips updated · Undo to restore');}catch(e){ctx.error=e.message;renderMapTooltip();}}
document.addEventListener('change',event=>{if((event.target?.hasAttribute?.('data-tip-extra')||['mapTipMode','mapTipShowValue','mapTipNumberFormat'].includes(event.target.id))&&$('mapTooltip'))syncMapTooltipControls();});

function renderTooltipFields(ctx){return `<section class="tooltip-extra-fields"><h4>Additional tooltip fields</h4>${ctx.type==='geo-route'?'':'<button class="subtle-button" data-action="map-tooltip-fields-example">Try additional fields example</button>'}<p class="hint">Up to four explicit source columns. Rules use only valid contributors to the main mark in the current period. Unique text reports differing values instead of choosing one; numeric rules exclude missing/invalid cells and disclose counts. Selected fields are published in tooltips and can appear in the optional source-data table.</p>${ctx.draft.geoTooltipFields.map((f,i)=>{const attr=key=>`data-tip-extra="${key}" data-tip-index="${i}"`,text=(key,label,max)=>field(label,`<input ${attr(key)} maxlength="${max}" value="${E(f[key])}">`);return `<fieldset><legend>Additional field ${i+1}</legend><div class="map-author-fields">${field('Source column',`<select ${attr('field')}><option value="">Choose a column…</option>${getFields(ctx.rows).map(name=>`<option value="${E(name)}" ${f.field===name?'selected':''}>${E(name)}</option>`).join('')}${f.field&&!getFields(ctx.rows).includes(f.field)?`<option selected value="${E(f.field)}">Missing: ${E(f.field)}</option>`:''}</select>`)}${field('Rule for contributing records',`<select ${attr('aggregation')}>${Object.entries(TOOLTIP_FIELD_METHODS).map(([key,label])=>`<option value="${key}" ${f.aggregation===key?'selected':''}>${label}</option>`).join('')}</select>`)}${text('label','Display label (blank uses column)',60)}${field('Number format',`<select ${attr('format')}>${[['auto','Automatic / exact'],['decimal','Decimal'],['compact','Compact'],['scientific','Scientific']].map(([key,label])=>`<option value="${key}" ${f.format===key?'selected':''}>${label}</option>`).join('')}</select>`)}${field('Decimal places',`<input ${attr('decimals')} type="number" min="0" max="6" step="1" value="${E(f.decimals)}">`)}${text('prefix','Value prefix',16)}${text('suffix','Value suffix / unit',16)}</div><button class="subtle-button" data-action="map-tooltip-extra-remove" data-index="${i}">Remove field</button></fieldset>`;}).join('')}<button class="secondary-button" data-action="map-tooltip-extra-add" ${ctx.draft.geoTooltipMode!=='custom'||ctx.draft.geoTooltipFields.length>=4?'disabled':''}>+ Add tooltip field</button></section>`;}
function syncTooltipFieldControls(){const root=$('mapTooltip');if(!root)return;const active=$('mapTipMode').value==='custom';for(const el of root.querySelectorAll('[data-tip-extra]')){const i=el.dataset.tipIndex,method=root.querySelector(`[data-tip-extra="aggregation"][data-tip-index="${i}"]`).value,format=root.querySelector(`[data-tip-extra="format"][data-tip-index="${i}"]`).value;el.disabled=!active||(method==='unique'&&['format','decimals','prefix','suffix'].includes(el.dataset.tipExtra))||(el.dataset.tipExtra==='decimals'&&format==='auto');}root.querySelector('[data-action="map-tooltip-extra-add"]').disabled=!active||root.querySelectorAll('.tooltip-extra-fields fieldset').length>=4;for(const button of root.querySelectorAll('[data-action="map-tooltip-extra-remove"]'))button.disabled=!active;}
function readTooltipFields(){const fields=structuredClone(mapTooltip.draft.geoTooltipFields);for(const el of $('mapTooltip').querySelectorAll('[data-tip-extra]')){if(el.disabled)continue;fields[Number(el.dataset.tipIndex)][el.dataset.tipExtra]=el.dataset.tipExtra==='decimals'?(el.value.trim()===''?NaN:Number(el.value)):el.value;}return fields;}
function editTooltipField(action,index){if(!mapTooltip||!$('mapTooltip')||$('mapTipMode').value!=='custom')return;readMapTooltip(false);if(action==='add'&&mapTooltip.draft.geoTooltipFields.length<4)mapTooltip.draft.geoTooltipFields.push(newTooltipField());if(action==='remove'&&Number.isInteger(index))mapTooltip.draft.geoTooltipFields.splice(index,1);mapTooltip.error='';renderMapTooltip();}

// V3.50 editorial table controls. Source records remain untouched.
function tableDataProperties(c,d){const fields=getFields(d.rows);return `<section><h4>Published columns</h4><p class="hint">Choose 1–8 columns. Selection order is the table order. Only these columns are included in the published table; each source row remains a record.</p><div class="ov-dimension-picker">${fields.map(f=>`<label><input type="checkbox" data-parallel-field="${E(f)}" ${(c.parallelFields||[]).includes(f)?'checked':''}> ${E(f)}</label>`).join('')}</div>${(c.parallelFields||[]).map((f,i)=>`<div class="inline-actions"><span>${i+1}. ${E(f)}</span><button type="button" class="subtle-button" data-table-move="${i}" data-table-direction="-1" aria-label="Move ${E(f)} earlier" ${i===0?'disabled':''}>↑</button><button type="button" class="subtle-button" data-table-move="${i}" data-table-direction="1" aria-label="Move ${E(f)} later" ${i===(c.parallelFields||[]).length-1?'disabled':''}>↓</button></div>`).join('')}<p class="hint">Use Preview settings for column labels, numeric formatting and graphics. No aggregation is applied.</p></section>`;}
function tableAppearanceProperties(c,d){const m=tableModel(d.rows,c),options=(items,value)=>items.map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${label}</option>`).join('');return `<section><h4>Editorial table</h4>${field('Rows per page',`<select data-setting="tablePageSize">${[10,25,50].map(n=>`<option value="${n}" ${Number(c.tablePageSize||25)===n?'selected':''}>${n}</option>`).join('')}</select>`)}<p class="hint">HTML tables use native search, sorting and pages. SVG, PNG, PDF, slide, dashboard and story views show one disclosed static page; export chart HTML for the full table. Percent expects fractions; currency is USD.</p>${m.columns.map((col,i)=>{const cfg=(c.tableColumnStyles||[]).find(x=>x.field===col.field)||{},attr=k=>`data-table-column-option="${k}" data-table-column-index="${i}"`;return `<fieldset><legend>${E(col.field)}${col.numeric?' · numeric':''}</legend>${field('Display label',`<input ${attr('label')} maxlength="120" value="${E(cfg.label||'')}" placeholder="${E(col.field)}">`)}${col.numeric?field('Number format',`<select ${attr('format')}>${options([['number','Number'],['fixed','Fixed decimals'],['percent','Percent (fraction × 100)'],['currency','Currency (USD)']],col.format)}</select>`)+field('Decimal places',`<input ${attr('decimals')} type="number" min="0" max="6" value="${col.decimals}">`)+field('In-cell graphic',`<select ${attr('visual')}>${options([['none','None'],['bar','Signed bar · full-column scale'],['heat','Intensity · distance from zero']],col.visual)}</select>`)+field('Prefix',`<input ${attr('prefix')} maxlength="24" value="${E(cfg.prefix||'')}">`)+field('Suffix / unit',`<input ${attr('suffix')} maxlength="24" value="${E(cfg.suffix||'')}">`):field('Show values as',`<select ${attr('display')}>${options([['text','Text'],['image','Image (https link or embedded image)'],['flag','Country flag + name']],cfg.display||'text')}</select>`)}<label class="checkbox-field"><input type="checkbox" ${attr('sticky')} ${cfg.sticky===true||cfg.sticky==='true'?'checked':''}> Keep visible when scrolling sideways</label></fieldset>`;}).join('')}<p class="hint">Bar and heat scales include zero and all values in each selected column. Search and pages keep those scales fixed. No claim of comparability across columns with different units.</p></section><section><h4>Sparkline column</h4>${sparklineControls(c,d)}</section>`;}
function sparklineControls(c,d){const numericCols=getFields(d.rows||[]).filter(f=>fieldType(d.rows||[],f)==='number'),chosen=Array.isArray(c.tableSparkFields)?c.tableSparkFields:[];return `<p class="hint">Add a small trend line to each row from two or more numeric columns, read in the order you tick them (for example 2021, 2022, 2023). Missing values break the line; nothing is interpolated.</p><div class="spark-field-list">${numericCols.map(f=>{const i=chosen.indexOf(f);return `<label class="checkbox-field"><input type="checkbox" data-spark-field="${E(f)}" ${i>=0?'checked':''}>${E(f)}${i>=0?` <span class="spark-order">${i+1}</span>`:''}</label>`;}).join('')||'<p class="hint">No numeric columns in this dataset.</p>'}</div>${chosen.length?field('Column heading',input('tableSparkLabel',c.tableSparkLabel||'Trend','text','maxlength="60"'))+field('Style',`<select data-setting="tableSparkStyle">${[['line','Line with end point'],['bars','Bars from zero']].map(([v,l])=>`<option value="${v}" ${(c.tableSparkStyle||'line')===v?'selected':''}>${l}</option>`).join('')}</select>`)+field('Scale',`<select data-setting="tableSparkScale">${[['row','Each row uses its own range (shape)'],['shared','Shared across all rows (magnitude)']].map(([v,l])=>`<option value="${v}" ${(c.tableSparkScale||'row')===v?'selected':''}>${l}</option>`).join('')}</select>`)+'<button type="button" class="subtle-button button-small" data-action="spark-clear">Remove sparkline column</button>':''}`;}
document.addEventListener('change',event=>{const el=event.target.closest?.('[data-spark-field]');if(!el)return;const c=chart();if(c?.type!=='editorial-table')return;trackChange();const list=(Array.isArray(c.tableSparkFields)?c.tableSparkFields:[]).filter(f=>f!==el.dataset.sparkField);if(el.checked&&list.length<24)list.push(el.dataset.sparkField);c.tableSparkFields=list;markDirty();renderChartPreview();renderEditorWarnings();renderInspector();});
function updateTableColumnOption(input){const c=chart(),d=chartDataset(c);if(c?.type!=='editorial-table'||!d)return;const fieldName=c.parallelFields?.[Number(input.dataset.tableColumnIndex)],key=input.dataset.tableColumnOption;if(!fieldName||!['label','format','decimals','visual','prefix','suffix','display','sticky'].includes(key))return;trackChange();const styles=(c.tableColumnStyles||[]).filter(x=>c.parallelFields.includes(x.field)).map(x=>({...x}));let cfg=styles.find(x=>x.field===fieldName);if(!cfg){cfg={field:fieldName};styles.push(cfg);}cfg[key]=key==='decimals'?Math.max(0,Math.min(6,Math.round(Number(input.value)||0))):key==='sticky'?input.checked:input.value;c.tableColumnStyles=styles;markDirty();renderChartPreview();renderEditorWarnings();}
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-table-move]'),c=chart();if(!button||button.disabled||c?.type!=='editorial-table')return;const i=Number(button.dataset.tableMove),j=i+Number(button.dataset.tableDirection),list=[...(c.parallelFields||[])];if(j<0||j>=list.length)return;trackChange();[list[i],list[j]]=[list[j],list[i]];c.parallelFields=list;markDirty();render();});


installIcons();
